# -*- coding: utf-8 -*-
"""〈固態物理〉（kss_）：全部課程（第 1～26 課）與互動元件。"""
from kx_base import *

JS = r"""
  /* 1. 布拉格繞射 */
  function initBragg(root, cfg) { head(root, cfg.q);
    var L = [['簡單立方（釙，a = 3.35 Å）', 3.35, 0], ['體心立方（鐵，a = 2.87 Å）', 2.87, 1], ['面心立方（銅，a = 3.61 Å）', 3.61, 2]], lam = 1.5406;
    var P = { k: 2, th: 21.7 }, view = el('div');
    presets(root, L.map(function (l) { return l[0]; }), function (i) { P.k = i; draw(); }, 2);
    var u1 = slider(root, '入射角 θ', 5, 60, 0.1, P.th, function (v) { return f1(v) + '°（2θ = ' + f1(2 * v) + '°）'; }, 'th', function (v) { P.th = v; draw(); });
    root.appendChild(view); var inf = info(root);
    function ok(h, k, l, t) { if (t === 1) return (h + k + l) % 2 === 0; if (t === 2) { var a = Math.abs(h % 2), b = Math.abs(k % 2), c = Math.abs(l % 2); return a === b && b === c; } return true; }
    function peaks(a, t) { var G = {}; for (var h = -4; h <= 4; h++) for (var k = -4; k <= 4; k++) for (var l = -4; l <= 4; l++) { var N = h * h + k * k + l * l; if (!N || !ok(h, k, l, t)) continue; var s = lam * Math.sqrt(N) / (2 * a); if (s >= 1) continue; if (!G[N]) G[N] = { N: N, m: 0, hkl: [Math.abs(h), Math.abs(k), Math.abs(l)].sort(function (x, y) { return y - x; }).join('') }; G[N].m++; }
      return Object.keys(G).map(function (n) { var g = G[n], th = Math.asin(lam * Math.sqrt(g.N) / (2 * a)); g.tt = 2 * th * 180 / Math.PI; g.d = a / Math.sqrt(g.N); g.I = g.m * (1 + Math.pow(Math.cos(2 * th), 2)) / (Math.pow(Math.sin(th), 2) * Math.cos(th)); return g; }).filter(function (g) { return g.tt <= 130; }).sort(function (x, y) { return x.tt - y.tt; }); }
    function draw() { var c = L[P.k], pk = peaks(c[1], c[2]), mx = 0; pk.forEach(function (g) { mx = Math.max(mx, g.I); });
      var d0 = pk[0].d, th = P.th * Math.PI / 180, pd = 2 * d0 * Math.sin(th) / lam, nI = Math.round(pd), near = Math.abs(pd - nI) < 0.03 && nI > 0;
      var o = '', sp = 46, y0 = 70, cx = 150;
      for (var r = 0; r < 3; r++) { var y = y0 + r * sp; o += ln(20, y, 280, y, 'var(--border)', 1, 'stroke-dasharray="3 3"'); for (var x = 30; x <= 270; x += 30) o += ci(x, y, 5, 'var(--text-muted)'); }
      var Lr = 120, col = near ? GN : RD;
      for (var r2 = 0; r2 < 2; r2++) { var yy = y0 + r2 * sp, xs = cx - Lr * Math.cos(th), ys = yy - Lr * Math.sin(th), xe = cx + Lr * Math.cos(th); o += ln(xs, ys, cx, yy, r2 ? OR : BL, 2.2) + ln(cx, yy, xe, ys, r2 ? OR : BL, 2.2, near ? '' : 'stroke-dasharray="5 3"'); }
      o += tx(cx, y0 + 2 * sp + 26, 'd = ' + f2(d0) + ' Å（' + pk[0].hkl.split('').join('') + ' 面）', 11, 'var(--text)');
      o += tx(cx, 20, '光程差 2d sin θ = ' + f2(pd) + ' λ', 12, col) + tx(cx, 36, near ? '相長干涉！（n = ' + nI + '）' : '相位不一致，互相抵消', 11, col);
      var g1 = svgw('0 0 300 210', o), dd = [];
      for (var t = 10; t <= 130; t += 0.1) { var I = 0; pk.forEach(function (g) { I += g.I / mx * 100 * Math.exp(-Math.pow((t - g.tt) / 0.45, 2)); }); dd.push([t, I]); }
      var c2 = chart(380, 230, [{ d: dd, c: PU, n: '繞射強度', w: 1.6 }], { x0: 10, x1: 130, y0: 0, y1: 115, xl: '2θ（度）', yl: '強度', vl: [{ x: 2 * P.th, c: RD, n: '目前 2θ' }] });
      view.innerHTML = '<div style="display:flex;flex-wrap:wrap;gap:6px;align-items:center"><div style="flex:2 1 220px">' + g1 + '</div><div style="flex:3 1 300px">' + c2 + '</div></div>';
      inf.innerHTML = '兩道 X 光從相鄰兩層原子面反射，下面那道多走了 <b>2d sin θ</b>。當它剛好是波長的整數倍（<b>2d sin θ = nλ</b>），兩道光相位一致、互相加強——這就是<b>布拉格定律</b>。<br>右圖是銅靶 X 光（λ = 1.54 Å）的粉末繞射圖：' + c[0] + ' 的繞射峰出現在 2θ = ' + pk.slice(0, 5).map(function (g) { return f1(g.tt) + '°（' + g.hkl + '）'; }).join('、') + '……' + (c[2] === 1 ? '<br>體心立方「缺」了 (100)、(111) 等 h + k + l 為奇數的峰：體心的原子把反射抵消了（消光規則）。' : c[2] === 2 ? '<br>面心立方只出現 h、k、l 全奇或全偶的峰——峰的「間隔模式」就是晶體結構的指紋。' : '<br>簡單立方的每一組 (hkl) 都會出現。') + small('強度只考慮多重度與勞侖茲－偏振因子，忽略原子散射因子與溫度效應；左圖示意最低指數的一組晶面。'); }
    u1();
  }

  /* 2. 晶格振動色散 */
  function initDisp(root, cfg) { head(root, cfg.q);
    var P = { r: 2, k: 0.5, br: 0 }, view = el('div'), us;
    presets(root, ['聲學支（相鄰原子同向）', '光學支（相鄰原子反向）'], function (i) { P.br = i; draw(); });
    var g = el('div', 'display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:0 12px'); root.appendChild(g);
    us = [slider(g, '兩種原子的質量比 M/m', 1, 5, 0.1, P.r, f1, 'r', function (v) { P.r = v; draw(); }), slider(g, '波數 k（× π/a）', 0.02, 1, 0.01, P.k, f2, 'k', function (v) { P.k = v; draw(); })];
    root.appendChild(view); var inf = info(root);
    function w2(k, m1, m2, s) { var A = 1 / m1 + 1 / m2, B = Math.sqrt(Math.max(0, A * A - 4 * Math.pow(Math.sin(k / 2), 2) / (m1 * m2))); return Math.sqrt(Math.max(0, A + s * B)); }
    function draw() { var m1 = 1, m2 = P.r, ac = [], op = [], top = w2(0, m1, m2, 1) * 1.1;
      for (var q = 0; q <= 1.0001; q += 0.01) { var k = q * Math.PI; ac.push([q, w2(k, m1, m2, -1)]); op.push([q, w2(k, m1, m2, 1)]); }
      var k = P.k * Math.PI, w = w2(k, m1, m2, P.br ? 1 : -1);
      var gapLo = w2(Math.PI, m1, m2, -1), gapHi = w2(Math.PI, m1, m2, 1);
      var c1 = chart(640, 240, [{ d: ac, c: BL, n: '聲學支', w: 2.4 }, { d: op, c: OR, n: '光學支', w: 2.4 }], { x0: 0, x1: 1, y0: 0, y1: top, xl: '波數 k（π/a）', yl: '頻率 ω', pts: [{ x: P.k, y: w, c: RD }] });
      var vr = 2 * 1 - m1 * w * w, ph = 1 + Math.cos(-k), qh = Math.sin(-k), den = ph * ph + qh * qh, vRe = vr * ph / den, vIm = -vr * qh / den, o = '', N = 8, cw = 70, amp = 18;
      var norm = Math.max(1, Math.hypot(vRe, vIm)); var aU = 1 / norm, vR = vRe / norm, vI = vIm / norm;
      for (var n = 0; n < N; n++) { var c = Math.cos(k * n), s = Math.sin(k * n), u = aU * c, v = vR * c - vI * s, x1 = 30 + n * cw, x2 = x1 + cw / 2; o += ln(x1 + u * amp, 40, x2 + v * amp, 40, 'var(--border)', 2) + (n < N - 1 ? ln(x2 + v * amp, 40, x1 + cw + aU * Math.cos(k * (n + 1)) * amp, 40, 'var(--border)', 2) : '') + ci(x1 + u * amp, 40, 9, BL) + ci(x2 + v * amp, 40, 9 + Math.min(6, (m2 - 1) * 1.5), OR); }
      var c2 = svgw('0 0 590 80', ln(10, 66, 580, 66, 'var(--border)', 1) + o + tx(295, 76, '原子位移的快照（藍：輕原子 m；橘：重原子 M）', 9.5, 'var(--text-muted)'));
      view.innerHTML = c1 + c2;
      inf.innerHTML = '晶體中的原子由化學鍵（像彈簧）相連，振動以波的形式傳播。量子化的晶格振動叫做<b>聲子</b>。<br>' + (P.br ? '<b>光學支</b>：同一個晶胞中的兩種原子<b>反向</b>振動。如果兩種原子帶相反的電荷（例如 NaCl），這種振動會產生振盪的電偶極，能和紅外光交互作用——所以叫「光學」支。' : '<b>聲學支</b>：k 很小時，相鄰原子幾乎一起移動，就是<b>聲波</b>：頻率和 k 成正比，斜率就是聲速。k 接近布里淵區邊界（π/a）時，曲線變平，波變成駐波。') + '<br>兩支之間有一段<b>頻隙</b>（ω 介於 ' + f2(gapLo) + ' 與 ' + f2(gapHi) + ' 之間）：' + (P.r < 1.05 ? '質量相同時頻隙消失，兩支在邊界相接。' : '這些頻率的振動無法在晶體中傳播。質量比越大，頻隙越寬。') + small('一維雙原子鏈，彈簧常數 K = 1、輕原子質量 m = 1；頻率以任意單位表示。'); }
    us.forEach(function (u) { u(); });
  }

  /* 3. 能帶與費米能階 */
  function initBand(root, cfg) { head(root, cfg.q);
    var M = [['銅（金屬）', 0], ['鍺', 0.66], ['矽', 1.12], ['砷化鎵', 1.42], ['氮化鎵', 3.4], ['鑽石', 5.5]];
    var P = { k: 2, T: 300, dop: 0 }, view = el('div'), us;
    presets(root, M.map(function (m) { return m[0]; }), function (i) { P.k = i; draw(); }, 2);
    presets(root, ['本質（未摻雜）', 'n 型（摻磷 10¹⁶ cm⁻³）', 'p 型（摻硼 10¹⁶ cm⁻³）'], function (i) { P.dop = i; draw(); });
    us = [slider(root, '溫度', 50, 800, 10, P.T, function (v) { return v + ' K（' + (v - 273) + ' °C）'; }, 'T', function (v) { P.T = v; draw(); })];
    root.appendChild(view); var inf = info(root);
    function sci(x) { if (!(x > 0)) return '0'; var e = Math.floor(Math.log10(x)), m = x / Math.pow(10, e); return (m >= 9.95 ? '1' : m.toFixed(1)) + ' × 10<sup>' + (m >= 9.95 ? e + 1 : e) + '</sup>'; }
    function draw() { var m = M[P.k], Eg = m[1], T = P.T, kT = 8.617e-5 * T, metal = Eg === 0, o = '';
      var Nc = 2.8e19 * Math.pow(T / 300, 1.5), Nv = 1.04e19 * Math.pow(T / 300, 1.5), ni = metal ? 0 : Math.sqrt(Nc * Nv) * Math.exp(-Eg / (2 * kT)), Nd = 1e16;
      var n = ni, p = ni; if (!metal && P.dop === 1) { n = Nd / 2 + Math.sqrt(Nd * Nd / 4 + ni * ni); p = ni * ni / n; } if (!metal && P.dop === 2) { p = Nd / 2 + Math.sqrt(Nd * Nd / 4 + ni * ni); n = ni * ni / p; }
      var Ec = metal ? 0 : Eg, EF = metal ? 0 : P.dop === 2 && p > 0 ? kT * Math.log(Nv / p) : n > 0 && isFinite(Math.log(Nc / n)) ? Ec - kT * Math.log(Nc / n) : Eg / 2;
      if (!metal) EF = Math.max(-0.5, Math.min(Eg + 0.5, EF));
      var emin = -2, emax = Math.max(3, Eg + 2), H = 250, T0 = 10; function Y(e) { return T0 + (emax - e) / (emax - emin) * H; }
      if (metal) { o += rc(100, Y(1.6), 160, Y(-2) - Y(1.6), 'rgba(58,110,165,0.12)', BL, 4); o += rc(100, Y(0), 160, Y(-2) - Y(0), 'rgba(58,110,165,0.55)', '', 0); o += tx(180, Y(1.2), '傳導帶（部分填滿）', 11, 'var(--text)'); }
      else { o += rc(100, Y(emax), 160, Y(Ec) - Y(emax), 'rgba(217,130,43,0.12)', OR, 4) + rc(100, Y(0), 160, Y(emin) - Y(0), 'rgba(58,110,165,0.55)', BL, 4) + tx(180, Y(emax) + 16, '傳導帶', 11, 'var(--text)') + tx(180, Y(-1.2), '價帶（幾乎填滿）', 11, '#fff');
        o += ln(88, Y(0), 88, Y(Ec), 'var(--text-muted)', 1) + tx(84, (Y(0) + Y(Ec)) / 2 + 3, 'Eg = ' + Eg + ' eV', 10, 'var(--text)', 'end');
        var r = rng(3), ne = Math.max(0, Math.min(40, Math.round(Math.log10(Math.max(n, 1)) * 3 - 15))), np = Math.max(0, Math.min(40, Math.round(Math.log10(Math.max(p, 1)) * 3 - 15)));
        for (var i = 0; i < ne; i++) o += ci(106 + r() * 148, Y(Ec) - 4 - r() * 14, 2.6, RD);
        for (var j = 0; j < np; j++) o += ci(106 + r() * 148, Y(0) + 4 + r() * 14, 2.8, 'var(--bg)', 'var(--text)', 1); }
      o += ln(90, Y(EF), 280, Y(EF), GN, 2, 'stroke-dasharray="6 3"') + tx(284, Y(EF) + 4, '費米能階 E<tspan font-size="8" dy="2">F</tspan>', 10.5, GN, 'start');
      var fd = 'M'; for (var e = emin; e <= emax; e += (emax - emin) / 200) { var f = 1 / (1 + Math.exp(Math.max(-60, Math.min(60, (e - EF) / kT)))); fd += (fd === 'M' ? '' : ' L') + n1(370 + f * 120) + ' ' + n1(Y(e)); }
      o += ln(370, T0, 370, T0 + H, 'var(--border)', 1) + ln(490, T0, 490, T0 + H, 'var(--border)', 1, 'stroke-dasharray="3 3"') + pa(fd.replace('M L', 'M'), PU, 2) + tx(430, T0 + H + 14, '佔據機率 f(E)：0 → 1', 9.5, 'var(--text-muted)') + tx(20, T0 + 8, '能量', 10, 'var(--text-muted)', 'start');
      view.innerHTML = svgw('0 0 560 280', o);
      var sig = metal ? '' : '每立方公分約有 <b>' + sci(n) + '</b> 個傳導電子（紅點，示意）、<b>' + sci(p) + '</b> 個電洞（空心點）。作為比較，固體每立方公分約有 5 × 10<sup>22</sup> 個原子。';
      inf.innerHTML = metal ? '<b>金屬</b>：最高的能帶只填了一部分，費米能階落在能帶<b>中間</b>。電子只要一點點能量，就能移到上方的空狀態而導電——所以金屬在任何溫度都能導電，而且溫度越高，晶格振動越劇烈，電阻反而<b>增加</b>。' :
        m[0] + '的能隙 ' + Eg + ' eV，在 ' + T + ' K 時：' + sig + '<br>' + (P.dop === 0 ? (Eg > 3 ? '能隙這麼大，熱能（kT ≈ ' + f2(kT * 1000) + ' meV）幾乎不可能把電子激發過去：<b>絕緣體</b>。' : '少量電子被熱激發到傳導帶，留下電洞：本質半導體的導電性<b>隨溫度急劇上升</b>（和金屬相反）。調高溫度看看。') : ni > Nd * 0.3 ? '溫度這麼高，熱激發的本質載子（約 ' + sci(ni) + ' cm⁻³）已經和摻雜量相當甚至更多，摻雜的效果被「淹沒」——這是晶片不能過熱的原因之一。' : P.dop === 1 ? '每個磷原子多一個電子，貢獻給傳導帶：電子濃度幾乎等於摻雜濃度，比本質濃度高出許多數量級，費米能階往上移到靠近傳導帶。' : '每個硼原子少一個電子，從價帶「拿走」電子而留下電洞：費米能階往下移到靠近價帶。') + small('使用矽的有效態密度（Nc、Nv ∝ T^1.5）近似所有半導體，並忽略能隙隨溫度的變化；摻雜假設完全游離。'); }
    us.forEach(function (u) { u(); });
  }

  /* 4. 德拜熱容 */
  function initDebye(root, cfg) { head(root, cfg.q);
    var M = [['鉛', 105], ['銅', 343], ['鋁', 428], ['矽', 645], ['鑽石', 2230]];
    var P = { k: 1, T: 100 }, view = el('div');
    presets(root, M.map(function (m) { return m[0] + '（θD ≈ ' + m[1] + ' K）'; }), function (i) { P.k = i; draw(); }, 1);
    var u1 = slider(root, '溫度', 2, 1000, 1, P.T, function (v) { return v + ' K'; }, 'T', function (v) { P.T = v; draw(); });
    root.appendChild(view); var inf = info(root);
    function ein(x) { if (x > 600) return 0; var e = Math.exp(-x); return x * x * e / Math.pow(1 - e, 2); }
    function deb(T, th) { var X = th / T, N = 200, h = X / N, s = 0; for (var i = 0; i <= N; i++) { var x = i * h, f = x < 1e-6 ? 0 : x > 600 ? 0 : Math.pow(x, 4) * Math.exp(-x) / Math.pow(1 - Math.exp(-x), 2); s += f * (i === 0 || i === N ? 1 : i % 2 ? 4 : 2); } return 3 * Math.pow(T / th, 3) * s * h / 3; }
    function draw() { var th = M[P.k][1], tE = 0.806 * th, a = [], b = [], c = [];
      for (var T = 2; T <= 1000; T += 4) { a.push([T, deb(T, th) * 24.94]); b.push([T, ein(tE / T) * 24.94]); c.push([T, 24.94]); }
      var cd = deb(P.T, th) * 24.94, ce = ein(tE / P.T) * 24.94;
      view.innerHTML = chart(640, 250, [{ d: c, c: GY, n: '杜隆－珀蒂（古典）3R', w: 1.5, dash: '6 4' }, { d: b, c: OR, n: '愛因斯坦模型', w: 2 }, { d: a, c: BL, n: '德拜模型', w: 2.4 }], { x0: 0, x1: 1000, y0: 0, y1: 28, xl: '溫度（K）', yl: 'J/(mol·K)', vl: [{ x: th, c: 'var(--text-muted)', n: 'θD' }], pts: [{ x: P.T, y: cd, c: RD }] });
      inf.innerHTML = M[P.k][0] + '在 ' + P.T + ' K 的莫耳熱容：德拜模型約 <b>' + f1(cd) + '</b> J/(mol·K)，是古典值 3R ≈ 24.9 的 ' + pct(cd / 24.94) + '。' +
        (P.T < th / 10 ? '<br>在 T ≪ θD 的低溫，熱容和 <b>T³</b> 成正比（德拜 T³ 定律）：溫度減半，熱容剩下約八分之一。愛因斯坦模型則下降得太快（指數衰減）——因為它忽略了低頻的聲學聲子（第 9 課），而低溫時正是這些「便宜」的振動模態被激發。' : P.T > th ? '<br>溫度遠高於德拜溫度時，所有的振動模態都被激發，回到古典的<b>杜隆－珀蒂定律</b>：每莫耳約 25 J/K，與材料無關。' : '<br>在德拜溫度附近，熱容從量子的低溫行為過渡到古典的高溫極限。') + (P.k === 4 ? '<br>鑽石的原子輕、鍵又硬，振動頻率極高（θD ≈ 2230 K）：室溫下它的熱容只有古典值的約四分之一——這正是 19 世紀令物理學家困惑、最後由量子理論解開的謎題。' : '') + small('愛因斯坦溫度取 θE ≈ 0.806 θD 以便比較；德拜溫度為近似值；實際測量值另含少量電子熱容與熱膨脹的修正。'); }
    u1();
  }
"""
KSSLIB = lib("kss-w", "__kssLib", JS, {"bragg": "initBragg", "disp": "initDisp", "band": "initBand", "debye": "initDebye"})
lesson, W = kit(u"💎", "kss-w", KSSLIB, u"本課以觀念與物理圖像為主，數學推導力求精簡；互動元件使用簡化模型，數值為近似值。")

BRAGG = W({"t": "bragg", "q": u"X 光繞射與布拉格定律："})
DISP = W({"t": "disp", "q": u"一維雙原子鏈的聲子色散："})
BAND = W({"t": "band", "q": u"能帶、能隙與費米能階："})
DEBYE = W({"t": "debye", "q": u"固體的熱容："})


MODULES = [
(u"模組 A｜晶體結構", [

lesson(u"固態物理是什麼", u"從原子到材料",
  [u"了解固態物理研究的對象與問題", u"認識量子力學在固體中的角色", u"了解固態物理對現代科技的影響"],
  [("h", u"10²³ 個原子"),
   ("p", u"一立方公分的銅含有約 8 × 10<sup>22</sup> 個原子。要逐一追蹤每一個原子和電子是不可能的。但固體中的原子通常排列成<strong>規則的週期結構</strong>——晶體——這個對稱性讓物理學家能用簡潔的理論，解釋為什麼銅導電、鑽石堅硬透明、矽是半導體、鐵有磁性。這就是<strong>固態物理</strong>（今天更廣泛地稱為<strong>凝態物理</strong>，是物理學中研究人數最多的領域）。"),
   ("h", u"古典物理的失敗"),
   ("p", u"19 世紀末的古典物理，對固體留下了許多謎題："),
   ("ul", [u"為什麼有些物質導電、有些不導電？電阻率可以相差 10<sup>30</sup> 倍以上。", u"金屬中有大量自由電子，為什麼它們對熱容幾乎沒有貢獻？", u"為什麼鑽石在室溫下的熱容遠低於古典的預測（" + LS(10) + u"）？", u"為什麼有些金屬中的電荷載子表現得像帶<strong>正電</strong>（" + LS(18) + u"）？"]),
   ("p", u"這些問題全都要等到<strong>量子力學</strong>（1920 年代）才得到解答（見" + X("quantum-mechanics", u"量子力學") + u"）。固態物理可以說是量子力學最成功、也最有用的應用。"),
   ("h", u"從物理到科技"),
   ("t", [u"固態物理的發現", u"帶來的科技"], [[u"能帶理論與半導體", u"電晶體（1947）、積體電路、電腦、手機"], [u"p-n 接面", u"二極體、LED、太陽能電池、雷射二極體"], [u"巨磁阻（1988）", u"硬碟的讀取頭、大容量儲存"], [u"超導", u"MRI、粒子加速器的磁鐵"], [u"液晶與光學性質", u"顯示器"], [u"量子霍爾效應", u"電阻的國際標準"]]),
   ("p", u"20 世紀後半的資訊革命，幾乎完全建立在固態物理的基礎上（見" + X("device-physics", u"半導體元件物理") + u"、" + X("computing-origins", u"計算的起源") + u"）。"),
   ("h", u"本課的路線"),
   ("p", u"我們從原子如何排列開始（模組 A、B），接著看原子如何振動（模組 C：聲子、熱容），然後是電子如何運動（模組 D：能帶、金屬與半導體），最後介紹半導體、磁性、超導與新奇的量子材料（模組 E）。"),
  ],
  u"一立方公分銅約 8 × 10^22 個原子無法逐一追蹤，但固體原子常排成規則週期結構晶體，對稱性使理論能解釋導電、硬度、半導體、磁性，即固態物理今稱凝態物理是研究人數最多的物理領域；古典物理留下謎題：電阻率相差 10^30 倍以上、自由電子對熱容幾無貢獻、鑽石室溫熱容遠低於古典預測、載子表現像帶正電，皆待 1920 年代量子力學解答；固態物理帶來電晶體 1947 積體電路、p-n 接面 LED 太陽能、巨磁阻 1988 硬碟、超導 MRI、液晶顯示、量子霍爾電阻標準，資訊革命建立於此；本課路線從原子排列、原子振動、電子運動到半導體磁性超導量子材料。",
  [u"為什麼晶體的週期性讓固體物理變得可以研究？", u"舉出兩個古典物理無法解釋的固體現象。", u"舉出三項建立在固態物理之上的科技。"]),

lesson(u"晶體與晶格", u"重複的圖案",
  [u"區分晶格與基底", u"理解單位晶胞的概念", u"區分晶體、多晶與非晶"],
  [("h", u"晶格加基底"),
   ("p", u"想像一張磁磚地板或一幅壁紙：一個圖案在平面上規則地重複。晶體也是如此，可以拆成兩部分："),
   ("ul", [u"<strong>晶格</strong>：一組數學上的點，從任何一點看出去，周圍的環境都完全相同。晶格點可以用整數組合表示：R = n₁a₁ + n₂a₂ + n₃a₃，其中 a₁、a₂、a₃ 是<strong>晶格向量</strong>。", u"<strong>基底</strong>：放在每一個晶格點上的原子（或原子團）。"]),
   ("p", u"<strong>晶體 = 晶格 + 基底</strong>。最簡單的晶體，每個晶格點上只有一個原子（例如銅）；複雜的晶體（例如蛋白質晶體）每個晶格點上可能有數萬個原子。"),
   ("h", u"單位晶胞"),
   ("p", u"能夠透過平移鋪滿整個空間的最小重複單元，叫做<strong>原始晶胞</strong>。為了方便看出對稱性，常常使用稍大的<strong>慣用晶胞</strong>——例如面心立方的慣用晶胞是一個立方體，裡面含 4 個晶格點（" + LS(3) + u"）。"),
   ("h", u"晶體、多晶與非晶"),
   ("t", [u"類型", u"結構", u"例子"], [[u"單晶", u"整塊材料的原子排列都沿同一個方向延續", u"矽晶圓、寶石、雪花（單一冰晶）"], [u"多晶", u"由許多微小的晶粒組成，各晶粒的方向不同", u"大多數的金屬、陶瓷"], [u"非晶（玻璃態）", u"短程有序、沒有長程的週期性", u"玻璃、非晶矽、某些塑膠"]]),
   ("p", u"半導體工業需要極純、極完美的<strong>單晶矽</strong>：用<strong>柴氏長晶法</strong>，把一小顆晶種浸入熔融的矽中，緩慢地旋轉拉起，長成直徑 30 公分、長度約兩公尺的圓柱形晶棒，雜質濃度可以低到十億分之一以下。"),
   ("h", u"為什麼原子要排整齊"),
   ("p", u"在低溫下，原子會選擇能量最低的排列。對大多數的物質，這種排列是週期性的——因為如果某個局部的排列能量最低，把它重複下去整體的能量也最低。快速冷卻時，原子來不及排好就被「凍結」，形成非晶態的玻璃。晶體的外形常常反映內部的原子排列：食鹽的立方體、石英的六角柱、雪花的六重對稱。"),
   ("p", u"延伸：" + X("materials-science", u"材料科學") + u"。"),
  ],
  u"晶體如磁磚壁紙由圖案規則重複，可拆成晶格（數學點集，每點環境相同，R = n1a1 + n2a2 + n3a3）與基底（放在晶格點上的原子或原子團），晶體 = 晶格 + 基底，銅每點一原子、蛋白質晶體每點數萬原子；能平移鋪滿空間的最小單元為原始晶胞，為看出對稱常用較大的慣用晶胞如面心立方含 4 個晶格點；單晶整塊方向延續如矽晶圓寶石雪花、多晶由不同方向晶粒組成如多數金屬陶瓷、非晶短程有序無長程週期如玻璃非晶矽；柴氏長晶法以晶種浸入熔融矽旋轉拉起長成直徑 30 公分長約兩公尺晶棒雜質低於十億分之一；低溫原子選能量最低排列多為週期性，快冷來不及排好成玻璃，晶體外形反映內部如食鹽立方石英六角柱雪花六重對稱。",
  [u"晶格和基底有什麼不同？", u"單晶、多晶與非晶有什麼不同？各舉一例。", u"為什麼快速冷卻容易形成玻璃？"]),

lesson(u"布拉維晶格與常見結構", u"14 種晶格",
  [u"認識 14 種布拉維晶格與 7 個晶系", u"熟悉 SC、BCC、FCC、HCP 結構", u"理解堆積率與配位數"],
  [("h", u"14 種可能"),
   ("p", u"1848 年，法國物理學家<strong>布拉維</strong>證明：三維空間中，滿足「每一點環境都相同」的晶格，只有 <strong>14 種</strong>，分屬 <strong>7 個晶系</strong>（立方、四方、正交、單斜、三斜、三方、六方）。加上基底的對稱性，所有的晶體結構可以歸入 <strong>230 種空間群</strong>。為什麼沒有五重對稱的晶格？因為正五邊形無法鋪滿平面——這個限制直到準晶的發現才被重新思考（" + LS(7) + u"）。"),
   ("h", u"立方晶系的三兄弟"),
   ("t", [u"結構", u"慣用晶胞內原子數", u"配位數", u"堆積率", u"例子"], [[u"簡單立方（SC）", u"1", u"6", u"52%", u"釙（唯一的元素例子）"], [u"體心立方（BCC）", u"2", u"8", u"68%", u"鐵（室溫）、鉻、鎢、鈉"], [u"面心立方（FCC）", u"4", u"12", u"74%", u"銅、鋁、金、銀、鎳"]]),
   ("p", u"<strong>配位數</strong>是每個原子最近鄰原子的數目；<strong>堆積率</strong>是原子（當作硬球）佔據的體積比例。"),
   ("h", u"最密堆積"),
   ("p", u"把相同的球堆得最密，有兩種方式：一層一層以 ABCABC… 的順序堆疊，得到 <strong>FCC</strong>；以 ABAB… 堆疊，得到<strong>六方最密堆積</strong>（HCP，例如鎂、鋅、鈦）。兩者的堆積率都是 π/(3√2) ≈ 74%。克卜勒在 1611 年猜想這就是最密的堆法，這個「克卜勒猜想」直到 1998 年才由<strong>黑爾斯</strong>用大量的電腦計算證明（2014 年完成形式化驗證）。水果攤上的柳丁，正是這樣堆的。"),
   ("h", u"有基底的結構"),
   ("ul", [u"<strong>鑽石結構</strong>：FCC 晶格，每個晶格點上有兩個原子。每個原子以四面體的方式和 4 個鄰居鍵結（sp³，見" + X("organic-chemistry", u"有機化學") + u"）。矽、鍺都是這個結構。", u"<strong>閃鋅礦結構</strong>：和鑽石一樣，但兩個原子不同，例如砷化鎵（GaAs）。", u"<strong>岩鹽結構</strong>：氯化鈉，FCC 晶格，基底是一個 Na 和一個 Cl。", u"<strong>鈣鈦礦結構</strong>：ABX₃，例如鈦酸鋇；新一代的鈣鈦礦太陽能電池正迅速發展。"]),
   ("h", u"同素異形與相變"),
   ("p", u"同一種元素在不同的溫度、壓力下可能有不同的結構。<strong>鐵</strong>在室溫是 BCC（α 鐵），加熱到 912 °C 以上變成 FCC（γ 鐵）——FCC 的空隙比較大，能溶入更多的碳。鋼鐵的<strong>熱處理</strong>（淬火、回火）正是利用這個相變來控制碳的分布與鋼的硬度（見" + X("materials-science", u"材料科學") + u"）。"),
  ],
  u"1848 年布拉維證明三維中每點環境相同的晶格只有 14 種分屬 7 晶系（立方四方正交單斜三斜三方六方），加上基底對稱共 230 種空間群，正五邊形無法鋪滿平面故無五重對稱晶格；簡單立方 1 原子配位 6 堆積 52% 唯一元素為釙、體心立方 2 原子配位 8 堆積 68% 如室溫鐵鉻鎢鈉、面心立方 4 原子配位 12 堆積 74% 如銅鋁金銀鎳；最密堆積 ABC 為 FCC、AB 為 HCP（鎂鋅鈦），皆 π/(3√2) ≈ 74%，克卜勒 1611 年猜想 1998 年黑爾斯以電腦證明 2014 年形式化驗證；鑽石結構 FCC 每點兩原子四面體鍵結如矽鍺、閃鋅礦如 GaAs、岩鹽 NaCl、鈣鈦礦 ABX3 如鈦酸鋇與鈣鈦礦太陽能電池；鐵室溫 BCC α 鐵 912 °C 以上 FCC γ 鐵空隙大溶碳多，鋼的熱處理利用此相變。",
  [u"BCC 和 FCC 的配位數與堆積率各是多少？", u"什麼是克卜勒猜想？", u"為什麼鋼的熱處理和鐵的相變有關？"]),

lesson(u"米勒指數", u"如何稱呼晶體中的平面",
  [u"學會求晶面的米勒指數", u"理解晶面間距", u"了解晶面方向對材料性質的影響"],
  [("h", u"為晶面命名"),
   ("p", u"晶體中可以畫出無數組平行的原子平面。1839 年，英國礦物學家<strong>米勒</strong>提出一套簡潔的標記法："),
   ("ol", [u"找出平面在三個晶軸上的<strong>截距</strong>（以晶格常數為單位）。例如 1、2、∞（平行於第三軸）。", u"取<strong>倒數</strong>：1、½、0。", u"化成<strong>最小的整數</strong>：(2 1 0)。"]),
   ("p", u"所以 <strong>(100)</strong> 是垂直於 x 軸的平面（立方體的一個面）、<strong>(110)</strong> 是沿著面對角線切開的平面、<strong>(111)</strong> 是切掉立方體一個角的斜面。負的指數在數字上方加一橫線。用大括號 {100} 表示所有對稱等價的晶面族（立方體的六個面）；用方括號 [100] 表示方向。"),
   ("h", u"晶面間距"),
   ("p", u"在立方晶體中，相鄰兩個 (hkl) 平面的距離是"),
   D(r"d_{hkl} = \frac{a}{\sqrt{h^2 + k^2 + l^2}}"),
   ("p", u"指數越大，平面越密集、間距越小、每一層平面上的原子也越稀疏。X 光繞射正是量測這些間距（" + LS(6) + u"）。"),
   ("h", u"方向很重要"),
   ("ul", [u"<strong>晶圓的切面</strong>：矽晶圓常用 (100) 面，因為它和氧化層之間的介面缺陷最少，適合製作 MOS 電晶體；(111) 面則用於某些功率元件。", u"<strong>蝕刻</strong>：氫氧化鉀溶液蝕刻矽時，(111) 面的速率比 (100) 面慢上百倍，所以會蝕刻出 54.7° 的完美斜面——這被用來製造微機電系統（MEMS）的結構。", u"<strong>解理面</strong>：晶體沿著特定的平面最容易裂開。寶石切割師利用鑽石的 {111} 解理面劈開原石；雲母可以剝成極薄的片。", u"<strong>塑性變形</strong>：金屬在原子最密集的平面上沿著最密集的方向滑移（FCC 的 {111}&lt;110&gt;），這和金屬的延展性有關（" + LS(8) + u"）。"]),
  ],
  u"1839 年米勒提出晶面標記法：找三晶軸截距、取倒數、化最小整數，如截距 1 2 ∞ 得 (210)；(100) 垂直 x 軸立方體一面、(110) 沿面對角線、(111) 切掉一角，負指數加橫線，{100} 為等價晶面族、[100] 為方向；立方晶體晶面間距 d = a/√(h² + k² + l²)，指數越大間距越小平面原子越稀疏，X 光繞射量測此；矽晶圓常用 (100) 因與氧化層介面缺陷最少適合 MOS，(111) 用於功率元件，KOH 蝕刻 (111) 比 (100) 慢上百倍形成 54.7° 斜面用於 MEMS，寶石切割利用鑽石 {111} 解理面、雲母剝薄片，FCC 在 {111}<110> 滑移與延展性有關。",
  [u"一個平面在三個軸上的截距是 2、3、∞，它的米勒指數是什麼？", u"立方晶體中，(110) 與 (111) 平面哪一個的間距較小？", u"為什麼矽晶圓的切面方向很重要？"]),

lesson(u"倒晶格與布里淵區", u"在波的空間中看晶體",
  [u"理解倒晶格的意義", u"理解布里淵區", u"了解倒晶格在繞射與能帶中的角色"],
  [("h", u"波的語言"),
   ("p", u"在晶體中傳播的東西——X 光、電子、晶格振動——都是<strong>波</strong>。描述波最自然的變數是<strong>波向量</strong> k（方向是傳播方向，大小是 2π/波長）。把晶格的週期性翻譯到「波向量的空間」，就得到<strong>倒晶格</strong>。"),
   ("h", u"倒晶格"),
   ("p", u"倒晶格的向量 G 滿足：對所有的晶格向量 R，e<sup>iG·R</sup> = 1。直觀地說：每一個倒晶格向量，對應到實空間中的一組晶面（" + LS(4) + u"）：G 的方向垂直於晶面、大小等於 2π/d。所以實空間的間距越小，倒空間的距離越大——兩者互為倒數，這就是名字的由來。數學上，這和傅立葉轉換是同一件事（見" + X("fourier-signal", u"傅立葉與訊號") + u"）：倒晶格就是晶體週期結構的傅立葉頻譜。"),
   ("h", u"繞射條件"),
   ("p", u"當入射波與散射波的波向量之差剛好是一個倒晶格向量（k′ − k = G），就會發生強烈的繞射。這個條件（勞厄條件）和布拉格定律（" + LS(6) + u"）完全等價，只是換了一種語言。X 光繞射圖上的每一個亮點，就是倒晶格上的一個點。"),
   ("h", u"布里淵區"),
   ("p", u"在倒晶格中，以一個點為中心，取所有離它比離其他倒晶格點更近的區域，就是<strong>第一布里淵區</strong>（1930 年由布里淵提出）。它的重要性在於："),
   ("ul", [u"在週期結構中，波向量 k 和 k + G 描述的其實是<strong>同一個</strong>狀態——所以只需要研究第一布里淵區內的 k 就夠了。", u"在布里淵區的邊界上，波剛好滿足布拉格繞射條件，被晶格強烈反射，形成駐波。這導致聲子的色散曲線在邊界變平（" + LS(9) + u"），以及電子的能帶在邊界打開<strong>能隙</strong>（" + LS(15) + u"）。"]),
   ("p", u"一維的布里淵區就是 −π/a &lt; k &lt; π/a；FCC 的布里淵區是一個截角八面體，BCC 的是菱形十二面體。能帶圖的橫軸，就是沿著布里淵區中幾個高對稱點（Γ、X、L、K……）之間的路徑。"),
   ("h", u"為什麼要繞這麼一大圈"),
   ("p", u"倒空間一開始看起來很抽象，但它把晶體中所有「波的問題」統一起來：繞射、聲子、電子能帶、光子晶體，全都在同一個舞台上演。熟悉倒空間，是讀懂固態物理文獻的關鍵。"),
  ],
  u"晶體中 X 光、電子、晶格振動都是波，以波向量 k（大小 2π/波長）描述，把晶格週期性翻譯到波向量空間即倒晶格；倒晶格向量 G 滿足 e^(iG·R) = 1，每個 G 對應一組晶面，方向垂直晶面大小 2π/d，實空間間距小倒空間距離大，數學上即傅立葉轉換；k′ − k = G 時強烈繞射即勞厄條件與布拉格定律等價，繞射亮點即倒晶格點；第一布里淵區為離中心點比其他倒晶格點更近的區域，1930 年布里淵提出，k 與 k + G 為同一狀態只需研究第一區，邊界滿足布拉格條件形成駐波使聲子色散變平與電子能帶打開能隙；一維為 −π/a < k < π/a，FCC 為截角八面體、BCC 為菱形十二面體，能帶圖橫軸沿高對稱點 Γ X L K；倒空間統一繞射聲子能帶光子晶體。",
  [u"倒晶格向量和實空間的晶面有什麼關係？", u"什麼是第一布里淵區？", u"為什麼在布里淵區的邊界會出現能隙？"]),
]),

(u"模組 B｜繞射與真實晶體", [

lesson(u"X 光繞射與布拉格定律", u"看見原子的排列",
  [u"理解布拉格定律", u"了解 X 光繞射的歷史與應用", u"學會從繞射圖推測晶體結構"],
  [("h", u"勞厄的想法"),
   ("p", u"1912 年，德國物理學家<strong>勞厄</strong>想到：如果 X 光是波長很短的電磁波，而晶體中的原子間距約為 10<sup>−10</sup> 公尺，那麼晶體就像一個天然的三維繞射光柵。他的同事做了實驗，果然在底片上看到規則排列的亮點。這一舉證明了兩件事：X 光是波，晶體中的原子確實規則排列。勞厄獲得 1914 年諾貝爾物理獎。"),
   ("h", u"布拉格父子"),
   ("p", u"1913 年，英國的<strong>布拉格父子</strong>（威廉．亨利．布拉格與威廉．勞倫斯．布拉格）提出了更直觀的解釋：把 X 光的繞射看成在一層一層的原子平面上的「反射」。"),
   D(r"2d\sin\theta = n\lambda"),
   ("p", u"從相鄰兩層平面反射的光，光程差是 2d sin θ。只有當它是波長的整數倍，兩道光才相長干涉。他們用這個方法解出了<strong>氯化鈉</strong>與<strong>鑽石</strong>的結構——第一次「看見」原子的排列。父子兩人同獲 1915 年諾貝爾物理獎；兒子勞倫斯當年 25 歲，至今仍是最年輕的諾貝爾物理獎得主。"),
   BRAGG,
   ("h", u"從繞射圖到結構"),
   ("p", u"<strong>粉末繞射</strong>把樣品磨成細粉，各種方向的晶粒都有，所以每一組晶面都會在特定的 2θ 產生一個繞射峰。峰的<strong>位置</strong>給出晶面間距（進而得到晶格常數與晶格類型），峰的<strong>強度</strong>反映晶胞中原子的種類與位置，峰的<strong>寬度</strong>可以估計晶粒的大小。每一種晶體都有獨特的「指紋」，資料庫中收錄了數十萬種，可以用來鑑定未知的物質（見" + X("analytical-chemistry", u"分析化學") + u"）。"),
   ("h", u"改變世界的繞射圖"),
   ("ul", [u"<strong>DNA 雙螺旋</strong>（1953）：<strong>羅莎琳．富蘭克林</strong>拍攝的「51 號照片」的 X 形圖案，讓華生與克里克推斷出螺旋結構（見" + X("genetics-dna", u"遺傳與 DNA") + u"）。", u"<strong>蛋白質結構</strong>：1958 年肯德魯解出肌紅蛋白，至今蛋白質資料庫中大部分的結構都來自 X 光晶體學。", u"<strong>藥物</strong>：霍奇金解出盤尼西林、維生素 B₁₂ 與胰島素的結構（1964 年諾貝爾化學獎）。"]),
   ("p", u"今天，<strong>同步輻射</strong>光源提供比實驗室強上億倍的 X 光（台灣新竹有國家同步輻射研究中心的台灣光子源）；電子與中子也能做繞射，各有所長：中子對輕原子（如氫）與磁結構特別敏感。"),
  ],
  u"1912 年勞厄想到晶體原子間距約 10^−10 公尺如三維繞射光柵，實驗看到規則亮點證明 X 光是波且原子規則排列，1914 年諾貝爾獎；1913 年布拉格父子把繞射看成原子平面的反射，2d sin θ = nλ，光程差為波長整數倍時相長干涉，解出氯化鈉與鑽石結構，1915 年同獲諾貝爾獎，勞倫斯 25 歲至今最年輕物理獎得主；粉末繞射各方向晶粒皆有，峰位置給晶面間距與晶格、強度反映原子種類位置、寬度估晶粒大小，資料庫數十萬種指紋可鑑定物質；1953 年富蘭克林 51 號照片 X 形圖案助華生克里克推斷 DNA 雙螺旋、1958 年肯德魯解出肌紅蛋白、霍奇金解盤尼西林維生素 B12 胰島素 1964 年諾貝爾化學獎；同步輻射強上億倍台灣新竹台灣光子源，電子與中子也能繞射，中子對氫與磁結構敏感。",
  [u"寫出布拉格定律，並說明每個符號的意義。", u"粉末繞射圖中，峰的位置、強度與寬度各提供什麼資訊？", u"X 光繞射對生物學有什麼重大貢獻？"]),

lesson(u"準晶與非晶", u"不按規則排列的固體",
  [u"了解準晶的發現與意義", u"理解非晶固體的結構", u"認識玻璃與非晶材料的應用"],
  [("h", u"「不可能」的繞射圖"),
   ("p", u"1982 年 4 月 8 日，以色列材料科學家<strong>謝赫特曼</strong>在美國國家標準局用電子顯微鏡觀察一種快速冷卻的鋁錳合金，看到了一張具有<strong>十重對稱</strong>（五重旋轉對稱）的繞射圖。根據晶體學，週期性的晶格不可能有五重對稱（" + LS(3) + u"）。他在筆記本上寫下三個問號。"),
   ("p", u"接下來的幾年，他遭受了強烈的質疑：研究團隊的主管請他離開；兩屆諾貝爾獎得主<strong>鮑林</strong>公開說：「世界上沒有準晶，只有準科學家。」1984 年論文發表後，越來越多的實驗室重現了結果。謝赫特曼獲得 2011 年諾貝爾化學獎，國際晶體學會也修改了「晶體」的定義：從「週期性排列」改為「具有本質上離散的繞射圖」。"),
   ("h", u"有序但不週期"),
   ("p", u"<strong>準晶</strong>是有序的——原子的排列遵循嚴格的規則，繞射圖有清晰的亮點——但永遠<strong>不會重複</strong>。最好的類比是 1970 年代數學家<strong>潘洛斯</strong>設計的<strong>潘洛斯鋪磚</strong>：只用兩種菱形，就能無縫地鋪滿平面，具有五重對稱，卻永遠不重複（見" + X("topology", u"拓撲學") + u"）。中世紀伊斯蘭建築的一些幾何裝飾，也呈現出類似準週期的圖案。2009 年，科學家甚至在一塊來自俄羅斯的隕石中找到了天然的準晶。"),
   ("h", u"非晶固體"),
   ("p", u"<strong>玻璃</strong>等非晶固體沒有長程的週期性，但仍有<strong>短程有序</strong>：例如石英玻璃中，每個矽原子仍然被四個氧原子以四面體包圍，只是這些四面體連接的角度是隨機的。它的繞射圖不是清晰的亮點，而是幾個模糊的「暈環」。"),
   ("p", u"玻璃轉變是凝態物理中仍未完全理解的問題之一：液體冷卻時黏度急劇上升，最後「卡住」成固體，但結構看起來仍然像液體。（「教堂的舊玻璃窗下面比較厚，是因為玻璃會慢慢流動」是一個常見的迷思：室溫下玻璃的流動在宇宙的年齡內都微不足道，窗戶不均勻是古代製造工藝造成的。）"),
   ("h", u"非晶材料的應用"),
   ("ul", [u"<strong>光纖</strong>：極純的石英玻璃，讓光能傳輸數十公里而衰減很小（見" + X("optics-lasers", u"光學與雷射") + u"）。", u"<strong>非晶矽</strong>：薄膜電晶體，驅動液晶顯示器的每一個像素；早期的計算機太陽能板。", u"<strong>金屬玻璃</strong>：快速冷卻的合金，沒有晶粒與差排（" + LS(8) + u"），強度高、彈性好。", u"<strong>相變記憶體</strong>：利用材料在晶態與非晶態之間切換，兩者的電阻與反射率不同——可覆寫光碟也是這個原理。"]),
  ],
  u"1982 年 4 月 8 日謝赫特曼觀察快冷鋁錳合金看到十重對稱繞射圖，週期晶格不可能五重對稱，筆記寫三個問號；遭強烈質疑被請離團隊，鮑林說世界上沒有準晶只有準科學家，1984 年發表後被重現，2011 年諾貝爾化學獎，晶體定義改為具本質離散繞射圖；準晶有序但永不重複，類比 1970 年代潘洛斯鋪磚兩種菱形五重對稱永不重複，中世紀伊斯蘭裝飾類似，2009 年在俄羅斯隕石找到天然準晶；玻璃非晶固體無長程週期但短程有序如石英玻璃矽被四氧四面體包圍，繞射為模糊暈環；玻璃轉變仍未完全理解，舊教堂玻璃下厚是製造工藝非流動；應用有光纖、非晶矽薄膜電晶體與早期計算機太陽能、金屬玻璃無晶粒差排強度高、相變記憶體與可覆寫光碟。",
  [u"為什麼謝赫特曼的發現一開始不被接受？", u"準晶和一般晶體有什麼相同與不同？", u"「舊玻璃窗下面比較厚是因為玻璃會流動」這個說法正確嗎？"]),

lesson(u"晶體缺陷", u"不完美的力量",
  [u"認識點缺陷、線缺陷與面缺陷", u"理解差排與金屬的強度", u"了解缺陷的有益用途"],
  [("h", u"沒有完美的晶體"),
   ("p", u"真實的晶體總有缺陷。而且令人驚訝的是，材料的許多重要性質——強度、導電性、顏色、擴散——常常不是由完美的晶格決定，而是由<strong>缺陷</strong>決定。"),
   ("h", u"點缺陷"),
   ("ul", [u"<strong>空位</strong>：一個晶格位置上少了原子。在任何高於絕對零度的溫度，熱力學都要求一定比例的空位存在（熵的貢獻，見" + X("statistical-physics", u"統計物理") + u"）。原子透過跳進相鄰的空位而<strong>擴散</strong>。", u"<strong>間隙原子</strong>：原子擠在晶格之間的空隙。鋼中的碳原子就在鐵晶格的間隙中，大幅提高了強度。", u"<strong>取代雜質</strong>：外來的原子取代了原本的原子。半導體的<strong>摻雜</strong>就是刻意加入取代雜質（" + LS(19) + u"）。", u"<strong>色心</strong>：寶石的顏色常來自微量的雜質或缺陷：剛玉（氧化鋁）本身無色，含少量鉻是紅寶石、含鐵和鈦是藍寶石。鑽石中的氮－空位中心（NV 中心）正被研究用於量子感測與量子計算。"]),
   ("h", u"差排：金屬為什麼軟"),
   ("p", u"如果要讓完美晶體中的一整層原子同時滑過另一層，計算出的強度比實際測到的金屬強度大了<strong>一千倍以上</strong>。1934 年，<strong>泰勒</strong>、<strong>奧羅萬</strong>與<strong>波拉尼</strong>各自提出答案：晶體中有一種線狀的缺陷——<strong>差排</strong>——像地毯上的一道皺褶。要移動整張地毯很難，但推著皺褶前進很容易：差排每次只需要打斷一排原子鍵，就能讓晶體一點一點地滑移。"),
   ("p", u"這解釋了金屬的<strong>延展性</strong>。反過來，要讓金屬變強，就要<strong>阻礙差排的移動</strong>：加入雜質原子（合金強化）、讓差排互相糾纏（加工硬化——反覆彎折鐵絲會越來越硬，最後斷掉）、減小晶粒（晶界阻擋差排）、析出細小的顆粒（航太鋁合金）。整個冶金學可以說就是「控制差排的藝術」（見" + X("materials-science", u"材料科學") + u"）。"),
   ("h", u"面缺陷"),
   ("p", u"多晶材料中，相鄰晶粒的方向不同，交界處叫做<strong>晶界</strong>。晶界會散射電子（增加電阻）、阻擋差排（增加強度）、成為腐蝕與擴散的捷徑。<strong>霍爾－佩奇關係</strong>指出：晶粒越細，材料越強。另一種面缺陷是<strong>疊差</strong>：ABCABC 的堆疊順序中出現一個錯誤（" + LS(3) + u"）。"),
   ("h", u"半導體中的缺陷"),
   ("p", u"在矽晶片中，一個不該存在的缺陷就可能讓一顆電晶體失效。晶圓廠在製程中嚴格控制污染與缺陷——無塵室的等級、極純的化學品——就是為了讓數十億顆電晶體都能正常運作（見" + X("device-physics", u"半導體元件物理") + u"）。"),
  ],
  u"真實晶體總有缺陷，強度導電性顏色擴散常由缺陷決定；點缺陷有空位（熱力學熵要求一定比例，原子跳入空位擴散）、間隙原子（鋼中碳在鐵間隙提高強度）、取代雜質（半導體摻雜）、色心（剛玉含鉻為紅寶石含鐵鈦為藍寶石，鑽石 NV 中心用於量子感測）；整層原子同時滑移的計算強度比實際大一千倍以上，1934 年泰勒奧羅萬波拉尼提出差排如地毯皺褶，每次只打斷一排鍵使晶體逐步滑移，解釋延展性；強化金屬要阻礙差排：合金強化、加工硬化（反覆彎折鐵絲變硬而斷）、細化晶粒、析出顆粒，冶金學是控制差排的藝術；晶界散射電子阻擋差排為腐蝕擴散捷徑，霍爾－佩奇關係晶粒越細越強，疊差為 ABC 順序錯誤；晶片一個缺陷可使電晶體失效，晶圓廠嚴控污染。",
  [u"為什麼實際的金屬強度遠低於完美晶體的理論強度？", u"列出兩種強化金屬的方法，並說明它們如何阻礙差排。", u"為什麼紅寶石是紅色的？"]),
]),

(u"模組 C｜晶格振動", [

lesson(u"晶格振動與聲子", u"原子的集體舞蹈",
  [u"理解晶格振動的色散關係", u"理解聲學支與光學支", u"理解聲子的概念"],
  [("h", u"原子與彈簧"),
   ("p", u"晶體中的原子並非靜止不動，而是在平衡位置附近不停地振動。原子之間的化學鍵，在小振幅時可以近似成<strong>彈簧</strong>（見" + X("differential-equations", u"微分方程") + u"的彈簧振子）。一個原子的振動會透過彈簧傳給鄰居，形成在晶體中傳播的<strong>波</strong>。"),
   ("h", u"色散關係"),
   ("p", u"對一維的原子鏈（質量 m、彈簧常數 K、間距 a），解運動方程式得到頻率 ω 與波數 k 的關係："),
   D(r"\omega(k) = 2\sqrt{\frac{K}{m}}\left|\sin\frac{ka}{2}\right|"),
   ("ul", [u"k 很小（波長很長）：ω ≈ (a√(K/m)) k，頻率和 k 成正比——這就是<strong>聲波</strong>，斜率就是聲速。", u"k 接近 π/a（布里淵區邊界，" + LS(5) + u"）：曲線變平，相鄰原子反向振動，形成駐波。", u"頻率有<strong>上限</strong>：比 2√(K/m) 更高的振動無法在晶體中傳播。"]),
   DISP,
   ("h", u"聲學支與光學支"),
   ("p", u"如果晶胞中有兩個原子（例如 NaCl），色散曲線分成兩支：<strong>聲學支</strong>（同一晶胞中的原子同向運動，長波長時是聲波）與<strong>光學支</strong>（兩種原子反向運動）。在三維的晶體中，每一支又有一個縱波與兩個橫波的模式。晶胞中有 p 個原子，就有 3p 支色散曲線。"),
   ("h", u"聲子"),
   ("p", u"量子力學告訴我們：每一個振動模式的能量是量子化的，只能是 ħω 的整數倍（加上零點能）。一個能量量子 ħω 叫做一個<strong>聲子</strong>——就像光的能量量子叫做光子。聲子是晶體中的「準粒子」：它不是一個真正的粒子，卻可以像粒子一樣被產生、消滅、散射、攜帶能量與動量。"),
   ("p", u"聲子無所不在："),
   ("ul", [u"<strong>熱容</strong>：固體吸收的熱，主要用來產生聲子（" + LS(10) + u"）。", u"<strong>熱傳導</strong>：絕緣體中的熱，靠聲子傳遞（" + LS(11) + u"）。", u"<strong>電阻</strong>：電子被聲子散射，是金屬在室溫下電阻的主要來源（" + LS(12) + u"）。", u"<strong>超導</strong>：電子透過交換聲子而互相吸引，形成庫柏對（" + LS(22) + u"）。"]),
   ("p", u"科學家用<strong>非彈性中子散射</strong>直接量測聲子的色散曲線：中子進入晶體，產生或吸收一個聲子，能量與動量的改變正好對應一個點 (k, ω)。布羅克豪斯因此獲得 1994 年諾貝爾物理獎。"),
  ],
  u"晶體原子在平衡位置附近振動，化學鍵小振幅近似彈簧，振動傳給鄰居形成波；一維原子鏈 ω = 2√(K/m)|sin(ka/2)|，k 小時頻率與 k 成正比為聲波斜率即聲速，k 接近 π/a 布里淵區邊界曲線變平相鄰原子反向成駐波，頻率有上限 2√(K/m)；晶胞兩原子如 NaCl 分聲學支（同向，長波為聲波）與光學支（反向），三維每支有一縱兩橫，p 個原子有 3p 支；振動能量量子化為 ħω 整數倍，能量量子為聲子是準粒子可產生消滅散射攜帶能量動量；聲子決定熱容、絕緣體熱傳導、金屬室溫電阻、超導庫柏對；非彈性中子散射直接量測色散，布羅克豪斯 1994 年諾貝爾物理獎。",
  [u"一維原子鏈的色散關係在 k 很小時有什麼特徵？代表什麼？", u"聲學支與光學支有什麼不同？", u"什麼是聲子？列舉兩個聲子扮演重要角色的現象。"]),

lesson(u"固體的熱容", u"愛因斯坦與德拜",
  [u"了解杜隆－珀蒂定律及其失敗", u"理解愛因斯坦模型與德拜模型", u"理解德拜溫度與 T³ 定律"],
  [("h", u"杜隆－珀蒂定律"),
   ("p", u"1819 年，法國的<strong>杜隆</strong>與<strong>珀蒂</strong>發現：許多固體元素的莫耳熱容都約等於 <strong>25 J/(mol·K)</strong>。古典的統計力學（能量均分定理）給出了漂亮的解釋：每個原子在三個方向振動，每個方向有動能與位能各 ½k<sub>B</sub>T，所以每莫耳的熱容是 3R ≈ 24.9 J/(mol·K)，與材料無關（見" + X("statistical-physics", u"統計物理") + u"）。"),
   ("h", u"低溫的反叛"),
   ("p", u"但到了 19 世紀末，實驗發現：在低溫下，所有固體的熱容都會<strong>下降</strong>，趨近絕對零度時趨近於零。<strong>鑽石</strong>即使在室溫下，熱容也只有古典值的約四分之一。古典物理無法解釋。"),
   ("h", u"愛因斯坦模型（1907）"),
   ("p", u"<strong>愛因斯坦</strong>把普朗克的量子化想法用在固體上：假設每個原子都是一個獨立的量子振子，以同一個頻率 ω<sub>E</sub> 振動，能量只能是 ħω<sub>E</sub> 的整數倍。當 k<sub>B</sub>T 遠小於 ħω<sub>E</sub> 時，熱能「付不起」一個能量量子，振動被「凍結」，熱容趨近於零。這是量子理論第一次被應用在光以外的地方，成功地解釋了熱容在低溫下降的趨勢。但在很低的溫度，它預測的熱容下降得太快（指數衰減）。"),
   ("h", u"德拜模型（1912）"),
   ("p", u"<strong>德拜</strong>改進了模型：原子不是獨立振動的，而是集體地形成各種波長的聲子（" + LS(9) + u"）。長波長的聲學聲子頻率很低，即使在極低溫也能被激發。他把聲子當作在晶體中傳播的聲波，頻率最高到一個截止值，對應的溫度叫做<strong>德拜溫度</strong> θ<sub>D</sub>。"),
   DEBYE,
   ("ul", [u"T ≫ θ<sub>D</sub>：回到杜隆－珀蒂定律。", u"T ≪ θ<sub>D</sub>：熱容 ∝ <strong>T³</strong>（德拜 T³ 定律），和實驗非常吻合。"]),
   ("p", u"德拜溫度反映了原子振動的典型頻率：原子越輕、鍵越硬，θ<sub>D</sub> 越高。鉛（重、軟）約 105 K，鑽石（輕、硬）約 2,230 K——所以室溫對鉛來說是「高溫」，對鑽石卻是「低溫」。"),
   ("h", u"電子的熱容"),
   ("p", u"金屬中有大量的自由電子，古典理論預期它們也會貢獻 (3/2)R 的熱容——但實驗上幾乎看不到。答案要等到費米－狄拉克統計（" + LS(13) + u"）：只有費米能階附近很少數的電子能被熱激發。在極低溫（幾 K 以下），電子的熱容（∝ T）會超過聲子的熱容（∝ T³）而成為主角。"),
  ],
  u"1819 年杜隆與珀蒂發現許多固體莫耳熱容約 25 J/(mol·K)，能量均分定理每原子三方向動能位能各 ½kBT 得 3R ≈ 24.9；19 世紀末發現低溫熱容下降趨零，鑽石室溫僅古典值約四分之一；1907 年愛因斯坦假設每原子為同頻率獨立量子振子，kBT 遠小於 ħωE 時振動凍結，是量子理論首次用於光以外，但低溫下降太快呈指數；1912 年德拜改為集體聲子，長波聲學聲子低溫也能激發，頻率截止對應德拜溫度 θD，T ≫ θD 回到杜隆－珀蒂、T ≪ θD 熱容 ∝ T³；原子越輕鍵越硬 θD 越高，鉛約 105 K 鑽石約 2,230 K；金屬自由電子熱容幾乎看不到，因費米－狄拉克統計只有費米能階附近少數電子可激發，極低溫電子熱容 ∝ T 超過聲子 ∝ T³。",
  [u"杜隆－珀蒂定律是什麼？古典物理如何解釋它？", u"德拜模型比愛因斯坦模型好在哪裡？", u"為什麼鑽石在室溫下的熱容遠低於古典值？"]),

lesson(u"熱傳導與熱膨脹", u"聲子的交通",
  [u"理解絕緣體與金屬的熱傳導機制", u"了解高導熱材料與熱管理", u"理解熱膨脹的微觀原因"],
  [("h", u"熱怎麼在固體中傳遞"),
   ("p", u"固體中的熱由兩種「載子」傳遞：<strong>聲子</strong>與<strong>自由電子</strong>。絕緣體中只有聲子；金屬中，電子通常是主要的熱載子。熱導率可以用類似氣體動力論的公式估計：κ ≈ ⅓ C v ℓ，其中 C 是熱容、v 是速度、ℓ 是<strong>平均自由徑</strong>（兩次散射之間走的距離，見" + X("thermo-heat", u"熱力學與熱傳") + u"）。"),
   ("h", u"聲子的散射"),
   ("p", u"如果原子之間的力完全是理想的彈簧（諧振），聲子會永遠不受干擾地傳播，熱導率無限大。真實的晶體中，聲子會被散射：被其他聲子（因為原子間的力不完全是線性的）、被缺陷與雜質、被晶界與表面。溫度越高，聲子越多、互相碰撞越頻繁，所以絕緣體的熱導率通常在高溫時下降。"),
   ("h", u"熱導率的比較"),
   ("t", [u"材料", u"熱導率（W/(m·K)，室溫約略值）"], [[u"鑽石", u"約 2,000（天然固體中最高之一）"], [u"銀", u"約 430"], [u"銅", u"約 400"], [u"矽", u"約 150"], [u"不鏽鋼", u"約 15"], [u"玻璃", u"約 1"], [u"木材", u"約 0.1～0.2"], [u"空氣", u"約 0.026"]]),
   ("p", u"鑽石不導電，熱導率卻是銅的五倍：它的原子輕、鍵極硬，聲子速度快、德拜溫度高（" + LS(10) + u"），室溫下聲子之間的碰撞很少。所以鑽石摸起來特別冰涼——一個簡單的鑑定方法。"),
   ("h", u"維德曼－夫蘭茲定律"),
   ("p", u"1853 年，維德曼與夫蘭茲發現：金屬的熱導率與電導率的比值，在相同溫度下大致相同。原因是兩者都由同一批自由電子傳遞——好的導電體也是好的導熱體。這也是為什麼鍋子用金屬做、把手用塑膠或木頭。"),
   ("h", u"熱管理"),
   ("p", u"現代晶片的功率密度可以超過爐子的電熱板。如果熱散不出去，溫度升高會讓電晶體變慢、漏電增加，甚至損壞。散熱片、熱管、導熱膏、液冷系統，都是為了把熱從晶片帶走（見" + X("hvac-refrigeration", u"冷凍空調") + u"）。反過來，<strong>熱電材料</strong>需要「導電好、導熱差」，利用溫差直接發電——太空探測器的同位素電源就是用這個原理。"),
   ("h", u"熱膨脹"),
   ("p", u"如果原子間的位能是完美的拋物線（彈簧），原子振動得再劇烈，平均位置也不會改變——不會熱脹冷縮。真實的位能曲線<strong>不對稱</strong>：把原子推近很難（排斥力急劇增加），拉開相對容易。溫度升高、振幅變大時，原子平均而言往「容易的那一邊」偏，間距就變大了。所以熱膨脹是原子間力的<strong>非諧性</strong>造成的——同樣的非諧性也造成了聲子之間的散射。鐵軌與橋梁必須留下伸縮縫；不同材料的熱膨脹係數不匹配，是晶片封裝中焊點斷裂的常見原因。"),
  ],
  u"固體熱由聲子與自由電子傳遞，絕緣體只有聲子金屬電子為主，κ ≈ ⅓Cvℓ，ℓ 為平均自由徑；理想諧振聲子不受干擾熱導率無限，真實聲子被其他聲子（非線性）、缺陷雜質、晶界表面散射，高溫聲子多碰撞頻繁熱導率下降；室溫約略熱導率鑽石約 2,000、銀約 430、銅約 400、矽約 150、不鏽鋼約 15、玻璃約 1、木材 0.1～0.2、空氣 0.026 W/(m·K)，鑽石不導電但導熱為銅五倍因原子輕鍵硬聲子快，摸起來冰涼可鑑定；1853 年維德曼－夫蘭茲定律金屬熱導與電導比值相同因同由自由電子傳遞；晶片功率密度超過電熱板需散熱片熱管導熱膏液冷，熱電材料導電好導熱差可溫差發電用於太空同位素電源；位能曲線不對稱推近難拉開易，振幅大平均間距變大即熱膨脹源於非諧性，鐵軌橋梁伸縮縫、晶片封裝焊點斷裂。",
  [u"為什麼鑽石不導電，卻是極好的熱導體？", u"什麼是維德曼－夫蘭茲定律？為什麼成立？", u"為什麼原子間力的「非諧性」會造成熱膨脹？"]),
]),

(u"模組 D｜固體中的電子", [

lesson(u"自由電子模型", u"電子的海洋",
  [u"了解德魯德模型的成功與失敗", u"理解索末菲的量子自由電子模型", u"理解歐姆定律的微觀解釋"],
  [("h", u"德魯德模型（1900）"),
   ("p", u"電子被發現（1897）後僅三年，德國物理學家<strong>德魯德</strong>就提出了金屬的模型：金屬中的價電子脫離原子，像氣體分子一樣在正離子之間自由運動，不時和離子碰撞。施加電場時，電子在兩次碰撞之間被加速，平均得到一個<strong>漂移速度</strong>，形成電流。"),
   D(r"\sigma = \frac{n e^2 \tau}{m}"),
   ("p", u"n 是電子密度、τ 是兩次碰撞之間的平均時間。這個簡單的模型推導出了<strong>歐姆定律</strong>，也解釋了維德曼－夫蘭茲定律（" + LS(11) + u"）。值得一提的是：電子的漂移速度非常慢——家用電線中大約每秒不到一公釐！但電場的訊號以接近光速傳播，所以打開開關燈就立刻亮。"),
   ("h", u"德魯德的失敗"),
   ("ul", [u"古典的電子氣應該貢獻 (3/2)R 的熱容，實驗上幾乎沒有（" + LS(10) + u"）。", u"計算出的平均自由徑和實際不符；電子並不是真的和每一個離子碰撞。", u"無法解釋為什麼有些物質是絕緣體或半導體（" + LS(16) + u"）。", u"無法解釋某些金屬的霍爾係數為正（" + LS(18) + u"）。"]),
   ("h", u"索末菲模型（1927～1928）"),
   ("p", u"<strong>索末菲</strong>保留了「自由電子」的圖像，但把古典統計換成<strong>量子的費米－狄拉克統計</strong>：電子遵守<strong>包立不相容原理</strong>，每個量子狀態最多只能容納一個電子（考慮自旋，每個能階兩個）。所以電子不能全部擠在最低能量，而是由下往上一層一層地填滿，直到<strong>費米能階</strong>（" + LS(13) + u"）。"),
   ("p", u"結果驚人：即使在絕對零度，金屬中的電子仍然以極高的速度運動——銅的費米速度約 1.6 × 10<sup>6</sup> 公尺/秒（光速的約 0.5%）。熱容的謎題也解開了：只有費米能階附近 k<sub>B</sub>T 範圍內的少數電子能被熱激發。"),
   ("h", u"電阻從哪裡來"),
   ("p", u"量子力學還帶來一個深刻的轉變：在<strong>完美的週期晶格</strong>中，電子波可以毫無阻礙地傳播，電阻為零（布洛赫定理，" + LS(14) + u"）。電阻來自偏離完美週期的東西：<strong>晶格振動</strong>（聲子，隨溫度增加）與<strong>雜質缺陷</strong>（與溫度無關，在低溫時留下「殘餘電阻」）。這就是為什麼金屬的電阻隨溫度升高而增加（馬西森規則）。"),
  ],
  u"1897 年發現電子三年後德魯德提出金屬價電子如氣體在正離子間自由運動碰撞，電場在碰撞間加速得漂移速度，σ = ne²τ/m 推導歐姆定律並解釋維德曼－夫蘭茲定律，漂移速度家用電線每秒不到一公釐但電場訊號近光速；德魯德失敗於電子熱容幾無、平均自由徑不符、無法解釋絕緣體半導體、霍爾係數為正；1927～1928 年索末菲改用費米－狄拉克統計，包立不相容每狀態一電子，電子由下往上填滿到費米能階，絕對零度電子仍高速運動銅費米速度約 1.6 × 10^6 m/s 約光速 0.5%，熱容謎題因只有費米能階附近 kBT 內電子可激發；完美週期晶格中電子波無阻礙傳播電阻為零，電阻來自聲子（隨溫度增加）與雜質缺陷（殘餘電阻），即馬西森規則。",
  [u"德魯德模型如何解釋歐姆定律？", u"為什麼打開開關燈就立刻亮，即使電子漂移得很慢？", u"在量子力學中，金屬的電阻來自哪裡？"]),

lesson(u"費米能階與費米－狄拉克分布", u"電子的填充規則",
  [u"理解費米能階與費米溫度", u"理解費米－狄拉克分布函數", u"理解態密度"],
  [("h", u"填滿的費米海"),
   ("p", u"想像一座有很多層的停車場，每一格只能停一輛車（包立不相容原理）。車子從最低層開始停，直到所有的車都停好。最後一輛車停的高度，就是<strong>費米能階</strong> E<sub>F</sub>。在絕對零度，E<sub>F</sub> 以下的狀態全部填滿、以上的全部空著。這片填滿的狀態叫做<strong>費米海</strong>。"),
   ("h", u"費米能量有多大"),
   ("p", u"金屬的費米能量通常是幾個電子伏特：銅約 7 eV。對應的<strong>費米溫度</strong> T<sub>F</sub> = E<sub>F</sub>/k<sub>B</sub> 約為 <strong>8 萬 K</strong>——遠高於金屬的熔點。所以在室溫（300 K）下，費米海幾乎沒有被「攪動」：熱能 k<sub>B</sub>T ≈ 0.026 eV，只能激發費米能階附近極薄一層的電子（" + LS(12) + u"）。"),
   ("h", u"費米－狄拉克分布"),
   ("p", u"在溫度 T 時，能量為 E 的狀態被電子佔據的機率是"),
   D(r"f(E) = \frac{1}{e^{(E - E_F)/k_B T} + 1}"),
   ("ul", [u"E 遠低於 E<sub>F</sub>：f ≈ 1，幾乎一定被佔據。", u"E 遠高於 E<sub>F</sub>：f ≈ e<sup>−(E−E_F)/k_BT</sup>，接近古典的波茲曼分布。", u"E = E<sub>F</sub>：f = ½（費米能階的另一種定義）。", u"從 1 降到 0 的過渡區寬度約為幾個 k<sub>B</sub>T。"]),
   ("p", u"費米與狄拉克在 1926 年各自獨立推導出這個分布。所有自旋為半整數的粒子（電子、質子、中子）都遵守它，叫做<strong>費米子</strong>（見" + X("statistical-physics", u"統計物理") + u"）。"),
   ("h", u"態密度"),
   ("p", u"<strong>態密度</strong> g(E) 是單位能量範圍內有多少個量子狀態。三維的自由電子 g(E) ∝ √E。物理性質常由「費米能階附近的態密度」決定：電子熱容、磁化率、超導性。在半導體中，能隙裡面沒有任何狀態（g = 0），這正是半導體與金屬的根本差異（" + LS(16) + u"）。"),
   ("h", u"天上的費米氣體"),
   ("p", u"費米子的「不相容」會產生一種壓力——<strong>簡併壓力</strong>，即使在絕對零度也存在。它撐住了<strong>白矮星</strong>（電子簡併壓力）與<strong>中子星</strong>（中子簡併壓力），對抗重力的塌縮。錢德拉塞卡計算出：白矮星的質量超過約 1.4 倍太陽質量時，電子簡併壓力就撐不住了（錢德拉塞卡極限）。同一條物理規律，從手中的銅線延伸到宇宙中的恆星殘骸。"),
  ],
  u"包立不相容如停車場每格一輛車，由下往上填到最後一輛的高度即費米能階，絕對零度以下全滿以上全空為費米海；銅費米能量約 7 eV 費米溫度約 8 萬 K 遠高於熔點，室溫 kBT ≈ 0.026 eV 只激發費米能階附近極薄一層；費米－狄拉克分布 f(E) = 1/(e^((E−EF)/kBT) + 1)，遠低於 EF 約 1、遠高於接近波茲曼、E = EF 為 ½、過渡寬約數個 kBT，1926 年費米與狄拉克獨立推導，半整數自旋粒子為費米子；態密度 g(E) 為單位能量狀態數，三維自由電子 ∝ √E，費米能階附近態密度決定電子熱容磁化率超導，半導體能隙內 g = 0；費米子不相容產生簡併壓力撐住白矮星與中子星，錢德拉塞卡極限約 1.4 倍太陽質量。",
  [u"用自己的話解釋什麼是費米能階。", u"為什麼室溫下只有很少數的電子能被熱激發？", u"簡併壓力在天文學中扮演什麼角色？"]),

lesson(u"布洛赫定理與週期位能", u"晶體中的電子波",
  [u"理解布洛赫定理", u"理解為什麼完美晶體沒有電阻", u"了解緊束縛的圖像"],
  [("h", u"不再自由的電子"),
   ("p", u"自由電子模型（" + LS(12) + u"）忽略了一件事：電子在晶體中運動時，會感受到正離子產生的<strong>週期性位能</strong>。這個位能的影響有多大？它能解釋為什麼有些物質是絕緣體嗎？"),
   ("h", u"布洛赫定理（1928）"),
   ("p", u"年輕的瑞士物理學家<strong>布洛赫</strong>在他的博士論文中證明了：在週期位能中，電子的波函數必然是這樣的形式："),
   D(r"\psi_k(\mathbf{r}) = e^{i\mathbf{k}\cdot\mathbf{r}}\,u_k(\mathbf{r})"),
   ("p", u"一個平面波 e<sup>ik·r</sup>，乘上一個和晶格有<strong>相同週期</strong>的函數 u<sub>k</sub>(r)。電子的波在每個原子附近「起伏」一下，但整體上仍然是一個貫穿整塊晶體的波，用波向量 k 來標記（k 只需要在第一布里淵區內，" + LS(5) + u"）。"),
   ("h", u"完美晶體沒有電阻"),
   ("p", u"布洛赫回憶，當他發現這個結果時非常高興：電子在完美的週期晶格中<strong>不會被散射</strong>，可以毫無阻礙地前進。這解決了德魯德模型的謎題：電子並不是在每個離子上碰撞，而是像波穿過規則排列的柵欄。電阻只來自<strong>破壞週期性</strong>的東西（聲子、雜質，" + LS(12) + u"）。極純的銅在極低溫下，電子的平均自由徑可以達到公釐甚至公分的尺度——是原子間距的上千萬倍。"),
   ("h", u"兩種極端的圖像"),
   ("ul", [u"<strong>近自由電子</strong>：位能很弱，電子大致是自由的，只在布里淵區邊界附近受到強烈影響（布拉格反射）。適合描述鈉、鋁等簡單金屬（" + LS(15) + u"）。", u"<strong>緊束縛</strong>：從孤立的原子出發。每個原子的電子軌域有確定的能階；把 N 個原子靠近，相鄰原子的軌域互相重疊，原本 N 個相同的能階分裂成 N 個非常接近的能階，形成一個<strong>能帶</strong>。軌域重疊越多，能帶越寬。適合描述過渡金屬的 d 電子與共價半導體。"]),
   ("p", u"兩種圖像從相反的方向出發，卻得到相同的結論：<strong>電子的允許能量形成能帶，能帶之間可能有能隙</strong>。"),
   ("h", u"計算能帶"),
   ("p", u"今天，物理學家用<strong>密度泛函理論</strong>（DFT，科恩獲 1998 年諾貝爾化學獎）在電腦上計算真實材料的能帶結構，預測新材料的性質，甚至在合成之前就篩選出有潛力的候選者——這是計算材料科學的核心工具。"),
  ],
  u"自由電子模型忽略正離子的週期性位能；1928 年布洛赫博士論文證明週期位能中波函數為 ψk(r) = e^(ik·r) uk(r)，平面波乘以與晶格同週期函數，用 k 標記只需第一布里淵區；完美週期晶格中電子不被散射如波穿過規則柵欄，解決德魯德謎題，電阻只來自破壞週期性的聲子雜質，極純銅極低溫平均自由徑可達公釐甚至公分為原子間距上千萬倍；近自由電子圖像位能弱只在布里淵區邊界受布拉格反射影響適合鈉鋁，緊束縛從孤立原子出發 N 個原子軌域重疊使 N 個相同能階分裂成能帶重疊越多越寬適合過渡金屬 d 電子與共價半導體，兩者皆得能帶與能隙；今以密度泛函理論 DFT（科恩 1998 年諾貝爾化學獎）計算能帶預測新材料。",
  [u"布洛赫定理的內容是什麼？", u"為什麼完美的晶體中電子不會被散射？", u"從緊束縛的角度，說明能帶是如何形成的。"]),

lesson(u"能帶的形成", u"允許與禁止的能量",
  [u"理解能隙在布里淵區邊界的形成", u"讀懂能帶圖", u"理解能帶填充的規則"],
  [("h", u"能隙從哪裡來"),
   ("p", u"在近自由電子的圖像中，電子的能量大致是 E = ħ²k²/2m（拋物線）。但當 k 接近布里淵區邊界（k = π/a）時，電子波的波長剛好滿足布拉格繞射的條件（" + LS(6) + u"）：被晶格強烈反射，向前與向後的波疊加成<strong>駐波</strong>。"),
   ("p", u"有兩種駐波：一種的電子密度集中在<strong>正離子的位置</strong>（受到較強的吸引，能量較低），另一種集中在<strong>離子之間</strong>（能量較高）。原本連續的能量在這裡被撕開，出現一段沒有任何電子狀態的能量範圍——<strong>能隙</strong>。能隙的大小約等於週期位能的傅立葉分量的兩倍。"),
   ("h", u"讀能帶圖"),
   ("p", u"能帶圖以波向量 k 為橫軸、能量 E 為縱軸，畫出所有允許的狀態。從圖中可以讀出："),
   ("ul", [u"<strong>能隙</strong>：沒有任何曲線經過的能量區間。", u"<strong>直接能隙與間接能隙</strong>：價帶頂與傳導帶底是否在同一個 k（" + LS(20) + u"）。", u"<strong>有效質量</strong>：曲線的彎曲程度（" + LS(17) + u"）。", u"<strong>群速度</strong>：曲線的斜率，v = (1/ħ) dE/dk。"]),
   ("h", u"填充的規則"),
   ("p", u"一個有 N 個原始晶胞的晶體，每一個能帶恰好有 N 個 k 值；考慮自旋，每個能帶最多容納 <strong>2N 個電子</strong>。所以："),
   ("ul", [u"每個晶胞貢獻<strong>奇數</strong>個價電子（例如鈉 1 個）：最高的能帶只填一半 → <strong>金屬</strong>。", u"每個晶胞貢獻<strong>偶數</strong>個價電子：可能剛好填滿幾個能帶 → <strong>絕緣體或半導體</strong>（如果能帶之間有能隙）；或者能帶重疊 → 仍然是金屬（例如鎂、鈣，每個原子 2 個價電子，卻是金屬）。"]),
   ("h", u"填滿的能帶不導電"),
   ("p", u"這是能帶理論最關鍵、也最反直覺的結論：一個<strong>完全填滿</strong>的能帶，對電流<strong>毫無貢獻</strong>。為什麼？施加電場時，每個電子都想加速，但所有的狀態都已經被佔據，沒有空位可以移過去；每一個往右走的電子，都有一個往左走的電子和它抵銷。導電需要<strong>部分填滿</strong>的能帶。這就是 1931 年<strong>威爾遜</strong>提出的金屬、絕緣體、半導體的分類基礎（" + LS(16) + u"）。"),
  ],
  u"近自由電子能量 E = ħ²k²/2m 拋物線，k 接近 π/a 時滿足布拉格條件被強烈反射成駐波，電子密度集中在離子處能量較低、在離子間較高，連續能量被撕開出現能隙，大小約為週期位能傅立葉分量兩倍；能帶圖以 k 為橫軸 E 為縱軸，可讀出能隙、直接與間接能隙、有效質量（彎曲程度）、群速度 v = (1/ħ)dE/dk；N 個原始晶胞每能帶 N 個 k 值含自旋容納 2N 電子，每晶胞奇數價電子最高能帶半滿為金屬如鈉，偶數可能填滿成絕緣體半導體或能帶重疊仍為金屬如鎂鈣；完全填滿的能帶對電流毫無貢獻因無空位且左右抵銷，導電需部分填滿，1931 年威爾遜據此分類金屬絕緣體半導體。",
  [u"為什麼在布里淵區邊界會出現能隙？", u"為什麼每個能帶最多可以容納 2N 個電子？", u"為什麼完全填滿的能帶不能導電？"]),

lesson(u"金屬、絕緣體與半導體", u"一張圖分出三類",
  [u"用能帶與費米能階區分三類材料", u"理解半導體導電性隨溫度的變化", u"認識常見半導體的能隙"],
  [("h", u"三種情況"),
   ("t", [u"類型", u"能帶圖", u"電阻率（Ω·m，約略）", u"溫度升高時"], [[u"金屬", u"費米能階落在能帶中間", u"10⁻⁸", u"電阻增加（聲子散射增加）"], [u"半導體", u"能帶填滿，能隙小（約 0.1～3 eV）", u"10⁻⁵～10³", u"電阻急劇下降（熱激發載子增加）"], [u"絕緣體", u"能帶填滿，能隙大（&gt; 約 3～4 eV）", u"10¹⁰ 以上", u"仍然幾乎不導電"]]),
   BAND,
   ("h", u"熱激發"),
   ("p", u"半導體與絕緣體的差別只是<strong>程度</strong>不同：在室溫下，熱能 k<sub>B</sub>T 約 0.026 eV。電子被激發越過能隙的機率大約正比於 e<sup>−E_g/2k_BT</sup>。矽（E<sub>g</sub> = 1.12 eV）：每立方公分約 10<sup>10</sup> 個本質載子——相對於 5 × 10<sup>22</sup> 個原子極少，但已經足以測量。鑽石（5.5 eV）：這個數字小到可以忽略，所以是絕緣體。"),
   ("p", u"這也解釋了半導體奇特的溫度行為：溫度升高，載子數以指數增加，電阻急劇下降——和金屬相反。<strong>熱敏電阻</strong>就是利用這個性質的溫度感測器。"),
   ("h", u"常見半導體"),
   ("t", [u"材料", u"能隙（eV，室溫）", u"特點與應用"], [[u"鍺 Ge", u"0.66", u"第一個電晶體（1947）"], [u"矽 Si", u"1.12", u"積體電路、太陽能電池的主流"], [u"砷化鎵 GaAs", u"1.42", u"直接能隙：雷射二極體、高頻元件"], [u"碳化矽 SiC", u"約 3.3", u"電動車的功率元件"], [u"氮化鎵 GaN", u"3.4", u"藍光 LED、快速充電器"], [u"鑽石 C", u"5.5", u"絕緣體（可摻雜成半導體）"]]),
   ("p", u"能隙大的「寬能隙半導體」（SiC、GaN）能承受更高的電壓與溫度，效率更高，是電動車、5G 基地台與快充的關鍵材料（見" + X("device-physics", u"半導體元件物理") + u"）。"),
   ("h", u"顏色與能隙"),
   ("p", u"能隙也決定了材料的<strong>顏色</strong>與<strong>透明度</strong>：光子能量小於能隙時無法被吸收，直接穿透。可見光的能量約 1.8～3.1 eV。鑽石的能隙 5.5 eV 遠高於可見光，所以透明無色；矽的能隙 1.12 eV 低於所有可見光，所以吸收全部可見光，呈現不透明的灰黑色金屬光澤；硫化鎘（約 2.4 eV）吸收藍光，呈黃色（" + LS(20) + u"）。"),
  ],
  u"金屬費米能階落在能帶中間電阻率約 10^−8 Ω·m 溫度升高電阻增加、半導體能帶填滿能隙約 0.1～3 eV 電阻率 10^−5～10^3 溫度升高電阻急降、絕緣體能隙大於約 3～4 eV 電阻率 10^10 以上；室溫 kBT 約 0.026 eV 激發機率約 e^(−Eg/2kBT)，矽 1.12 eV 本質載子每立方公分約 10^10 相對 5 × 10^22 原子極少但可測，鑽石 5.5 eV 可忽略為絕緣體，熱敏電阻利用半導體溫度行為；鍺 0.66 第一個電晶體、矽 1.12 積體電路太陽能、GaAs 1.42 直接能隙雷射高頻、SiC 約 3.3 電動車功率元件、GaN 3.4 藍光 LED 快充、鑽石 5.5，寬能隙半導體耐高壓高溫用於電動車 5G 快充；光子能量小於能隙穿透，可見光約 1.8～3.1 eV，鑽石透明、矽灰黑金屬光澤、硫化鎘約 2.4 eV 吸收藍光呈黃色。",
  [u"金屬與半導體的電阻隨溫度的變化有什麼不同？為什麼？", u"為什麼鑽石是透明的，矽卻是不透明的？", u"為什麼電動車需要寬能隙半導體？"]),

lesson(u"有效質量與電洞", u"晶體中的準粒子",
  [u"理解有效質量的概念", u"理解電洞是什麼", u"了解有效質量的應用"],
  [("h", u"晶體中的電子「變重」或「變輕」"),
   ("p", u"在晶體中，電子不只受到外加電場的力，還受到晶格週期位能的複雜作用。巧妙的是，這些複雜的作用可以全部「打包」進一個參數：<strong>有效質量</strong> m*。電子在外力下的反應，就像一個質量為 m* 的自由粒子："),
   D(r"\frac{1}{m^*} = \frac{1}{\hbar^2}\frac{d^2E}{dk^2}"),
   ("p", u"能帶曲線彎得越厲害（曲率大），有效質量越小，電子越「靈活」。例如砷化鎵傳導帶的電子有效質量只有自由電子的約 7%，所以電子遷移率很高，適合高速元件；矽約為 0.26 倍（傳導率有效質量）。在能帶的頂端，曲線向下彎，有效質量甚至是<strong>負的</strong>。"),
   ("h", u"電洞"),
   ("p", u"考慮一個幾乎填滿、只缺少<strong>一個</strong>電子的價帶。與其追蹤剩下的 10<sup>23</sup> 個電子，不如追蹤那一個「空位」。這個空位的行為，就像一個帶<strong>正電</strong>、具有<strong>正的</strong>有效質量的粒子——叫做<strong>電洞</strong>。"),
   ("p", u"一個比喻：一排坐滿的座位只空了一個。當旁邊的人移進空位，空位就往反方向移動了一格。人往左移，「空位」往右移。在電場中，價帶的電子往一個方向移動，電洞就往相反的方向移動——表現得就像正電荷。"),
   ("h", u"電洞是真的嗎"),
   ("p", u"電洞不是一個「真的」粒子，而是<strong>準粒子</strong>——就像聲子一樣（" + LS(9) + u"）。但它的效應是完全真實的：霍爾效應（" + LS(18) + u"）可以直接量到載子帶正電；p 型半導體的導電主要靠電洞（" + LS(19) + u"）；p-n 接面、電晶體、LED、太陽能電池，全都依賴電子與電洞的互動。"),
   ("h", u"準粒子的世界"),
   ("p", u"凝態物理的一個核心思想是：一大群強烈互相作用的粒子，其低能量的激發往往可以描述成一些<strong>弱相互作用的準粒子</strong>，各自有有效質量、電荷、自旋。電子在晶體中「穿上」了晶格的外衣，變成了有效質量不同的「準電子」；除了聲子與電洞，還有激子（電子與電洞的束縛態）、磁振子（自旋波，" + LS(21) + u"）、極化子……甚至在石墨烯中，電子表現得像<strong>沒有質量</strong>的粒子（" + LS(23) + u"）。這種「湧現」的觀點，正如安德森在 1972 年的名言：「多者異也」（More is different）。"),
  ],
  u"晶體中電子受週期位能複雜作用可打包成有效質量 m*，1/m* = (1/ħ²) d²E/dk²，曲線彎得越厲害有效質量越小越靈活，GaAs 傳導帶電子約自由電子 7% 遷移率高適合高速元件，矽約 0.26 倍，能帶頂端有效質量為負；幾乎填滿只缺一個電子的價帶，追蹤空位比追蹤 10^23 個電子容易，空位表現如帶正電且有效質量為正的粒子即電洞，如一排座位空一格人往左移空位往右移；電洞為準粒子但效應真實，霍爾效應量到正載子、p 型半導體靠電洞、p-n 接面電晶體 LED 太陽能皆依賴電子電洞；凝態核心思想為強作用粒子群的低能激發可描述為弱作用準粒子，有激子、磁振子、極化子，石墨烯電子如無質量粒子，安德森 1972 年名言多者異也。",
  [u"有效質量和能帶曲線的形狀有什麼關係？", u"用自己的比喻說明電洞為什麼表現得像正電荷。", u"什麼是準粒子？舉兩個例子。"]),

lesson(u"霍爾效應", u"載子的身分證",
  [u"理解古典霍爾效應的原理", u"學會用霍爾效應量測載子的種類與濃度", u"了解霍爾感測器的應用"],
  [("h", u"一個研究生的實驗"),
   ("p", u"1879 年，美國約翰霍普金斯大學的研究生<strong>霍爾</strong>想知道：磁場作用在載流導線上的力，究竟是作用在導線本身，還是作用在導線中流動的電荷上？他把一片薄金箔通上電流、放進垂直的磁場，在金箔的兩側量到了一個微小的橫向電壓——<strong>霍爾電壓</strong>。當時連電子都還沒被發現（1897）。"),
   ("h", u"原理"),
   ("p", u"電流 I 沿著樣品流動，磁場 B 垂直於樣品。移動的電荷受到<strong>勞侖茲力</strong>（見" + X("electromagnetism", u"電磁學") + u"），被推向樣品的一側，在兩側累積正負電荷，形成橫向的電場。當電場力剛好抵銷勞侖茲力時達到平衡："),
   D(r"V_H = \frac{IB}{n q t}"),
   ("p", u"t 是樣品的厚度、n 是載子濃度、q 是載子的電荷。"),
   ("h", u"從霍爾電壓讀出什麼"),
   ("ul", [u"<strong>正負號</strong>：電子與電洞被推向同一側（因為電荷與速度方向都相反），但累積的電荷符號相反——所以霍爾電壓的正負直接告訴我們載子是<strong>電子</strong>還是<strong>電洞</strong>。", u"<strong>載子濃度</strong>：V<sub>H</sub> 與 n 成反比。載子越少，霍爾電壓越大——所以半導體的霍爾效應比金屬大得多。", u"<strong>遷移率</strong>：結合電導率，可以算出載子的遷移率 μ = σ/(nq)。"]),
   ("h", u"正電荷之謎"),
   ("p", u"實驗發現：鋅、鈹、鎘等金屬的霍爾係數是<strong>正的</strong>——好像導電的是正電荷！自由電子模型完全無法解釋（" + LS(12) + u"）。能帶理論給出了答案：在這些金屬中，費米面附近的能帶接近填滿，導電的主角是<strong>電洞</strong>（" + LS(17) + u"）。霍爾效應成了能帶理論最有力的證據之一。"),
   ("h", u"霍爾感測器"),
   ("p", u"霍爾效應被製成小巧便宜的<strong>磁場感測器</strong>，無所不在：手機的電子羅盤、筆記型電腦闔上螢幕時的偵測、汽車的輪速感測器（ABS）、無刷馬達的轉子位置偵測、電流感測器（不需要接觸導線就能量電流）。半導體材料（例如砷化銦）的載子濃度低，霍爾電壓大，最適合做感測器。"),
   ("p", u"一百年後，霍爾效應在極低溫與強磁場的二維電子系統中展現了驚人的量子版本——<strong>量子霍爾效應</strong>（" + LS(24) + u"）。"),
  ],
  u"1879 年約翰霍普金斯大學研究生霍爾想知道磁力作用在導線或電荷，薄金箔通電放入垂直磁場量到橫向霍爾電壓，當時電子尚未發現；電流沿樣品磁場垂直，勞侖茲力把電荷推向一側累積形成橫向電場平衡，V_H = IB/(nqt)；霍爾電壓正負告訴載子是電子或電洞、與載子濃度成反比故半導體比金屬大、結合電導率得遷移率 μ = σ/(nq)；鋅鈹鎘霍爾係數為正自由電子模型無法解釋，能帶理論指出費米面附近能帶接近填滿主角是電洞，是能帶理論有力證據；霍爾感測器用於手機電子羅盤、筆電闔蓋偵測、汽車輪速 ABS、無刷馬達、非接觸電流感測，砷化銦載子濃度低最適合；百年後出現量子霍爾效應。",
  [u"霍爾電壓是如何產生的？", u"如何用霍爾效應判斷載子是電子還是電洞？", u"舉兩個霍爾感測器的應用。"]),
]),

(u"模組 E｜半導體與新奇材料", [

lesson(u"摻雜與 p-n 接面", u"控制半導體的關鍵",
  [u"理解 n 型與 p 型摻雜", u"理解 p-n 接面與空乏區", u"理解二極體的整流作用"],
  [("h", u"純矽幾乎不導電"),
   ("p", u"室溫下純矽每立方公分只有約 10<sup>10</sup> 個載子（" + LS(16) + u"），電阻很高，而且隨溫度劇烈變化——不適合做元件。半導體真正的威力在於：只要加入<strong>極微量</strong>的雜質，就能把導電性提高數百萬倍，而且精確地控制載子是電子還是電洞。這叫做<strong>摻雜</strong>。"),
   ("h", u"n 型與 p 型"),
   ("ul", [u"<strong>n 型</strong>：矽有 4 個價電子。摻入 5 價的<strong>磷</strong>或砷，四個電子和矽鍵結，多出的第五個電子只被很鬆地束縛（約 0.045 eV），室溫下幾乎全部進入傳導帶。多數載子是<strong>電子</strong>（negative）。", u"<strong>p 型</strong>：摻入 3 價的<strong>硼</strong>，少一個電子形成鍵，從鄰近「借」一個電子，在價帶留下一個<strong>電洞</strong>。多數載子是電洞（positive）。"]),
   ("p", u"典型的摻雜濃度是每百萬個矽原子中只有約一個雜質原子（10<sup>16</sup> cm<sup>−3</sup>），卻讓載子濃度增加了約一百萬倍。這也說明為什麼半導體需要極高的純度：意外的雜質會破壞精心設計的摻雜。"),
   ("h", u"p-n 接面"),
   ("p", u"把 p 型與 n 型半導體接在一起：n 區的電子擴散到 p 區與電洞結合，p 區的電洞擴散到 n 區。接面附近留下沒有可移動載子、只有固定離子的區域，叫做<strong>空乏區</strong>。這些離子形成內建電場，阻止載子繼續擴散，達到平衡。"),
   ("h", u"二極體"),
   ("ul", [u"<strong>順向偏壓</strong>（p 接正、n 接負）：外加電壓抵銷內建電場，空乏區變窄，載子大量流過，電流隨電壓指數增加。矽二極體約在 0.6～0.7 V 開始明顯導通。", u"<strong>逆向偏壓</strong>：空乏區變寬，幾乎沒有電流（只有極小的漏電流）。"]),
   ("p", u"電流只能單向流動——這就是<strong>整流</strong>：把交流電轉成直流電，每個充電器裡都有。p-n 接面是幾乎所有半導體元件的基本單元：LED（" + LS(20) + u"）、太陽能電池、光偵測器，以及雙極電晶體（兩個背對背的接面）。"),
   ("h", u"電晶體的誕生"),
   ("p", u"1947 年 12 月，貝爾實驗室的<strong>巴丁</strong>與<strong>布拉頓</strong>在鍺晶體上做出了第一個點接觸電晶體；他們的主管<strong>肖克利</strong>隨後發明了接面電晶體。三人共獲 1956 年諾貝爾物理獎（巴丁後來又因超導理論再獲一次，" + LS(22) + u"）。今天一顆先進的晶片上有數百億顆電晶體，每一顆的通道只有幾十個原子寬（見" + X("device-physics", u"半導體元件物理") + u"、" + X("chip-layout", u"晶片佈局") + u"）。"),
  ],
  u"純矽室溫每立方公分約 10^10 載子電阻高且隨溫度劇變，摻雜加入極微量雜質可提高導電性數百萬倍並控制載子種類；n 型摻 5 價磷或砷，第五個電子束縛約 0.045 eV 室溫幾乎全進傳導帶多數載子為電子，p 型摻 3 價硼少一電子借鄰近電子留電洞多數載子為電洞；典型摻雜每百萬矽原子約一個雜質 10^16 cm^−3 載子增加約百萬倍，需極高純度；p-n 接面電子電洞互相擴散結合，留下只有固定離子的空乏區形成內建電場達平衡；順向偏壓空乏區變窄電流指數增加矽約 0.6～0.7 V 導通，逆向偏壓空乏區變寬幾無電流，單向導電即整流，是 LED 太陽能光偵測器雙極電晶體基本單元；1947 年 12 月貝爾實驗室巴丁布拉頓在鍺上做出點接觸電晶體，肖克利發明接面電晶體，1956 年共獲諾貝爾獎巴丁後再因超導獲獎，今晶片數百億電晶體通道僅數十原子寬。",
  [u"n 型與 p 型半導體分別摻入什麼元素？多數載子是什麼？", u"什麼是空乏區？它是如何形成的？", u"為什麼 p-n 接面只能讓電流單向流動？"]),

lesson(u"光學性質與 LED", u"光與固體的對話",
  [u"理解直接與間接能隙", u"理解 LED 與太陽能電池的原理", u"了解藍光 LED 的故事"],
  [("h", u"吸收與發光"),
   ("p", u"光子能量大於能隙時，能把價帶的電子激發到傳導帶，留下電洞——光被<strong>吸收</strong>。反過來，傳導帶的電子落回價帶與電洞結合，可以放出一個能量約等於能隙的光子——<strong>發光</strong>。所以能隙決定了半導體吸收與發出的光的顏色（" + LS(16) + u"）。"),
   ("h", u"直接與間接能隙"),
   ("p", u"光子的動量非常小，所以電子吸收或放出光子時，波向量 k 幾乎不變（在能帶圖上「垂直」躍遷）。"),
   ("ul", [u"<strong>直接能隙</strong>（GaAs、GaN、InP）：價帶頂與傳導帶底在同一個 k。電子可以直接落下發光，效率很高。", u"<strong>間接能隙</strong>（矽、鍺）：兩者在不同的 k。電子要落下，必須同時和一個聲子交換動量（" + LS(9) + u"），三方參與的過程機率很低，大部分能量變成熱。"]),
   ("p", u"這就是為什麼<strong>矽幾乎不能用來做 LED 或雷射</strong>，發光元件要用 III-V 族化合物半導體；但矽吸收光沒有問題（只是需要比較厚的材料），所以矽仍然是太陽能電池的主流。"),
   ("h", u"LED"),
   ("p", u"<strong>發光二極體</strong>（LED）是一個順向偏壓的 p-n 接面（" + LS(19) + u"）：電子從 n 區、電洞從 p 區注入接面，結合時放出光子。改變半導體的組成（例如在 GaN 中加入不同比例的銦），就能調整能隙與顏色。LED 把電能轉換成光的效率遠高於白熾燈（白熾燈大部分的能量變成熱），壽命也長得多。"),
   ("h", u"藍光 LED"),
   ("p", u"紅光與綠光 LED 在 1960～70 年代就已出現，但藍光 LED 遲遲做不出來：需要能隙約 2.7 eV 以上的材料，而氮化鎵的高品質晶體與 p 型摻雜被認為幾乎不可能。日本的<strong>赤崎勇</strong>與<strong>天野浩</strong>堅持研究 GaN，在 1989 年左右做出了 p 型 GaN；<strong>中村修二</strong>在一家小公司（日亞化學）發展出量產的方法，1993 年推出高亮度的藍光 LED。三人獲得 2014 年諾貝爾物理獎。藍光 LED 加上黃色螢光粉就成了<strong>白光 LED</strong>，徹底改變了照明，也是今天手機與電視背光的基礎（見" + X("optics-lasers", u"光學與雷射") + u"）。"),
   ("h", u"太陽能電池"),
   ("p", u"LED 倒過來就是<strong>太陽能電池</strong>：光子在 p-n 接面附近產生電子－電洞對，被空乏區的內建電場分開，形成電流。單一接面的理論效率上限約 33%（蕭克利－奎伊瑟極限）：能量低於能隙的光子無法被吸收，能量高於能隙的部分變成熱。商用矽太陽能電池的效率約 20%～25%；把不同能隙的材料堆疊（多接面電池），效率可以超過 40%，用於人造衛星。"),
  ],
  u"光子能量大於能隙激發電子留電洞為吸收，傳導帶電子落回與電洞結合放出約能隙能量光子為發光，能隙決定吸收與發光顏色；光子動量很小躍遷 k 幾乎不變，直接能隙 GaAs GaN InP 價帶頂與傳導帶底同 k 發光效率高，間接能隙矽鍺需同時與聲子交換動量機率低能量變熱，故矽不能做 LED 雷射需 III-V 族，但矽吸光沒問題仍為太陽能主流；LED 為順向偏壓 p-n 接面電子電洞結合發光，GaN 加銦調能隙顏色，效率遠高於白熾燈壽命長；紅綠 LED 1960～70 年代已有，藍光需約 2.7 eV 以上，赤崎勇與天野浩約 1989 年做出 p 型 GaN，中村修二在日亞化學發展量產 1993 年推出高亮度藍光 LED，2014 年諾貝爾物理獎，藍光加黃色螢光粉為白光 LED；太陽能電池光子產生電子電洞對被內建電場分開，單接面理論上限約 33% 蕭克利－奎伊瑟極限，商用矽約 20%～25%，多接面超過 40% 用於衛星。",
  [u"直接能隙與間接能隙有什麼不同？為什麼矽不適合做 LED？", u"為什麼藍光 LED 的發明如此重要？", u"太陽能電池的效率為什麼有理論上限？"]),

lesson(u"磁性", u"電子的自旋與排列",
  [u"區分抗磁性、順磁性與鐵磁性", u"理解交換作用與磁區", u"了解巨磁阻與資訊儲存"],
  [("h", u"磁性的來源"),
   ("p", u"物質的磁性主要來自<strong>電子</strong>：電子有<strong>自旋</strong>（一個內在的磁矩）與軌道運動。在大多數的原子與分子中，電子成對排列，磁矩互相抵銷。只有含有<strong>未成對電子</strong>的原子（例如鐵、鈷、鎳、稀土元素）才有淨的磁矩（見" + X("quantum-mechanics", u"量子力學") + u"）。"),
   ("h", u"三種基本的磁性"),
   ("t", [u"類型", u"行為", u"例子"], [[u"抗磁性", u"被磁場微弱地排斥；所有物質都有", u"水、銅、石墨；強磁場可以讓青蛙飄浮（2000 年搞笑諾貝爾獎）"], [u"順磁性", u"被磁場微弱地吸引，移除磁場後消失", u"鋁、氧氣（液態氧會被吸在磁鐵兩極之間）"], [u"鐵磁性", u"磁矩自發地平行排列，形成永久磁鐵", u"鐵、鈷、鎳、釹鐵硼"]]),
   ("h", u"交換作用"),
   ("p", u"為什麼鐵中相鄰原子的磁矩會自發地朝同一個方向排列？直覺上，兩個小磁鐵之間的磁力太弱了，室溫的熱擾動就能打亂它們。1928 年，<strong>海森堡</strong>指出真正的原因是一種純粹的量子效應——<strong>交換作用</strong>：來自包立不相容原理與電子之間的庫侖排斥。它的強度比磁偶極力大上千倍。"),
   ("p", u"溫度升高時，熱擾動最終會打敗交換作用：超過<strong>居禮溫度</strong>，鐵磁性消失、變成順磁性。鐵的居禮溫度約 770 °C；釹鐵硼磁鐵約 310～400 °C（依成分而定）。"),
   ("h", u"磁區"),
   ("p", u"既然鐵是鐵磁性的，為什麼一根普通的鐵釘沒有磁性？因為它內部分成許多微小的<strong>磁區</strong>，每個磁區內的磁矩整齊排列，但不同磁區的方向各不相同，整體互相抵銷——這樣可以降低向外的磁場能量。放進外加磁場，與磁場同向的磁區長大，鐵釘就被磁化了。"),
   ("h", u"其他磁序"),
   ("ul", [u"<strong>反鐵磁性</strong>：相鄰磁矩反向排列，淨磁矩為零（例如氧化錳）。尼爾因此獲得 1970 年諾貝爾物理獎。", u"<strong>亞鐵磁性</strong>：反向排列但大小不同，留下淨磁矩——例如<strong>磁鐵礦</strong>（Fe₃O₄），人類最早認識的天然磁石，指南針的起源。"]),
   ("h", u"巨磁阻與硬碟"),
   ("p", u"1988 年，<strong>費爾</strong>與<strong>格林貝格</strong>各自發現：由磁性層與非磁性層交替組成的奈米多層膜，電阻會隨著相鄰磁性層的磁化方向（平行或反平行）而大幅改變——<strong>巨磁阻</strong>（GMR）。它讓硬碟的讀取頭能偵測極微小的磁區，在 1990 年代後期帶來了儲存密度的爆炸性成長。兩人獲得 2007 年諾貝爾物理獎。這也開啟了<strong>自旋電子學</strong>：同時利用電子的電荷與自旋；磁阻式記憶體（MRAM）是其中一個應用。"),
  ],
  u"磁性主要來自電子自旋與軌道運動，成對電子抵銷只有未成對電子原子如鐵鈷鎳稀土有淨磁矩；抗磁性被微弱排斥所有物質皆有如水銅石墨強磁場讓青蛙飄浮 2000 年搞笑諾貝爾獎、順磁性微弱吸引移除即消失如鋁與液態氧、鐵磁性磁矩自發平行形成永久磁鐵如鐵鈷鎳釹鐵硼；磁偶極力太弱，1928 年海森堡指出交換作用來自包立原理與庫侖排斥強上千倍，超過居禮溫度鐵磁性消失，鐵約 770 °C、釹鐵硼約 310～400 °C；鐵釘內分許多磁區方向各異抵銷以降低磁場能量，外加磁場使同向磁區長大而磁化；反鐵磁性相鄰反向淨磁矩零如氧化錳尼爾 1970 年諾貝爾獎、亞鐵磁性反向大小不同如磁鐵礦 Fe3O4 指南針起源；1988 年費爾與格林貝格發現多層膜巨磁阻 GMR 使硬碟讀取頭偵測微小磁區，2007 年諾貝爾獎，開啟自旋電子學與 MRAM。",
  [u"為什麼大多數物質沒有明顯的磁性？", u"什麼是交換作用？為什麼需要它來解釋鐵磁性？", u"為什麼一根普通的鐵釘沒有磁性，卻能被磁鐵吸引並磁化？"]),

lesson(u"超導概要", u"零電阻與完全抗磁",
  [u"了解超導的發現與基本特徵", u"了解 BCS 理論的核心概念", u"認識高溫超導與應用"],
  [("h", u"電阻突然消失"),
   ("p", u"1911 年，荷蘭的<strong>昂內斯</strong>剛成功液化氦氣（4.2 K），用它冷卻水銀，發現在約 4.2 K 時，水銀的電阻<strong>突然降到零</strong>——不是很小，而是無法量測地等於零。在超導線圈中感應出的電流，可以持續流動數年而不衰減。昂內斯獲得 1913 年諾貝爾物理獎（見" + X("superconductivity", u"超導") + u"）。"),
   ("h", u"邁斯納效應"),
   ("p", u"1933 年，<strong>邁斯納</strong>與<strong>奧森菲爾德</strong>發現超導體的第二個特徵：它會把磁場<strong>完全排出</strong>體外（完全抗磁性）。這不只是「零電阻」的結果，而是一個獨立的熱力學相。把一塊磁鐵放在冷卻的超導體上，磁鐵會<strong>懸浮</strong>起來——這是超導最經典的示範。"),
   ("h", u"BCS 理論"),
   ("p", u"超導的微觀機制困擾了物理學家將近半個世紀。1957 年，<strong>巴丁</strong>、<strong>庫柏</strong>與<strong>施里弗</strong>提出了 <strong>BCS 理論</strong>："),
   ("ol", [u"一個電子經過時，吸引附近帶正電的離子，造成晶格的局部變形（產生聲子，" + LS(9) + u"）。", u"變形的區域帶有多餘的正電荷，吸引另一個電子。", u"結果，兩個電子透過晶格間接地互相吸引，形成<strong>庫柏對</strong>。", u"庫柏對的行為像玻色子，大量地凝聚到同一個量子狀態，集體地運動——不會被個別的雜質或聲子散射，所以沒有電阻。"]),
   ("p", u"一個有力的證據是<strong>同位素效應</strong>：用較重的同位素替換，超導溫度會降低——證明晶格振動確實參與其中。BCS 三人獲得 1972 年諾貝爾物理獎；巴丁因此成為唯一兩度獲得諾貝爾物理獎的人（" + LS(19) + u"）。"),
   ("h", u"高溫超導"),
   ("p", u"傳統超導體的臨界溫度都很低（約 30 K 以下）。1986 年，IBM 蘇黎世實驗室的<strong>貝德諾茲</strong>與<strong>穆勒</strong>在一種銅氧化物陶瓷中發現了約 35 K 的超導，隔年就獲得諾貝爾獎。1987 年，朱經武與吳茂昆等人發現 YBCO 在約 93 K 超導——第一次高於<strong>液態氮的沸點</strong>（77 K），可以用便宜的液態氮冷卻。銅氧化物超導的機制至今仍未有共識，是凝態物理最大的未解問題之一。（2023 年轟動一時的「LK-99 室溫超導」宣稱，很快被各國實驗室的重複實驗否定。）"),
   ("h", u"應用"),
   ("ul", [u"<strong>MRI</strong>：超導線圈產生強而穩定的磁場（見" + X("medical-imaging", u"醫學影像") + u"）。", u"<strong>粒子加速器</strong>：大型強子對撞機使用超導磁鐵彎曲質子束。", u"<strong>磁浮列車</strong>：日本的中央新幹線使用超導磁浮。", u"<strong>量子電腦</strong>：超導量子位元是目前主流的技術之一（見" + X("quantum-computing", u"量子計算") + u"）。", u"<strong>SQUID</strong>：極靈敏的磁場感測器，可量測大腦的微弱磁場。"]),
  ],
  u"1911 年昂內斯液化氦氣 4.2 K 冷卻水銀，約 4.2 K 電阻突然降到零，超導線圈電流可持續數年，1913 年諾貝爾獎；1933 年邁斯納與奧森菲爾德發現超導體完全排出磁場為獨立熱力學相，磁鐵懸浮；1957 年 BCS 理論：電子吸引正離子使晶格變形（聲子），變形區吸引另一電子，兩電子間接吸引成庫柏對，庫柏對如玻色子凝聚集體運動不被散射，同位素效應證明晶格參與，1972 年諾貝爾獎巴丁唯一兩度獲物理獎；傳統超導約 30 K 以下，1986 年 IBM 蘇黎世貝德諾茲與穆勒銅氧化物約 35 K 隔年獲獎，1987 年朱經武吳茂昆等 YBCO 約 93 K 首次高於液態氮 77 K，銅氧化物機制仍無共識，2023 年 LK-99 室溫超導宣稱被否定；應用有 MRI、LHC 超導磁鐵、中央新幹線超導磁浮、超導量子位元、SQUID 量測大腦磁場。",
  [u"超導體有哪兩個基本特徵？", u"說明 BCS 理論中庫柏對的形成機制。", u"為什麼 YBCO 在 93 K 超導是一個重要的突破？"]),

lesson(u"石墨烯與二維材料", u"只有一個原子厚",
  [u"了解石墨烯的發現與性質", u"理解狄拉克錐與無質量電子", u"認識其他二維材料與扭轉電子學"],
  [("h", u"用膠帶拿到諾貝爾獎"),
   ("p", u"長久以來，理論認為嚴格的二維晶體在熱力學上不穩定，無法獨立存在。2004 年，英國曼徹斯特大學的<strong>海姆</strong>與<strong>諾沃肖洛夫</strong>做了一件看似簡單的事：用<strong>透明膠帶</strong>反覆黏貼石墨，把它一層一層撕薄，最後在矽晶片上找到了只有<strong>一個原子厚</strong>的碳層——<strong>石墨烯</strong>。他們在 2010 年獲得諾貝爾物理獎。（海姆也是 2000 年用磁場讓青蛙飄浮而獲得搞笑諾貝爾獎的人，" + LS(21) + u"。）"),
   ("h", u"驚人的性質"),
   ("ul", [u"<strong>強度</strong>：碳－碳鍵極強，石墨烯是已知抗拉強度最高的材料之一。", u"<strong>導電與導熱</strong>：電子遷移率極高；熱導率可與鑽石相比（" + LS(11) + u"）。", u"<strong>透明</strong>：單層只吸收約 2.3% 的可見光——這個數字恰好等於 π 乘以精細結構常數。", u"<strong>不透氣</strong>：連氦原子都無法穿過完美的石墨烯。"]),
   ("h", u"狄拉克錐"),
   ("p", u"石墨烯最奇特的是它的<strong>能帶結構</strong>。碳原子排成蜂巢狀的六角形晶格，在布里淵區的角落（K 點），價帶與傳導帶剛好在一點相接，附近的能量和動量成<strong>線性</strong>關係（E = ±ħv<sub>F</sub>|k|），形狀像兩個尖端相對的圓錐——<strong>狄拉克錐</strong>。"),
   ("p", u"線性的色散意味著電子的有效質量為零（" + LS(17) + u"），行為就像相對論中<strong>無質量的粒子</strong>（例如光子），只是速度約為光速的 1/300。這讓石墨烯成為在桌上研究相對論量子力學（狄拉克方程式）的實驗室。它沒有能隙，所以很難直接做成數位電路的開關——這是石墨烯電子學的一大挑戰。"),
   ("h", u"二維材料家族"),
   ("ul", [u"<strong>六方氮化硼</strong>（hBN）：結構像石墨烯，但是絕緣體，常作為其他二維材料的「墊子」。", u"<strong>過渡金屬二硫族化物</strong>（例如 MoS₂）：有能隙的二維半導體，單層時變成直接能隙（" + LS(20) + u"），被研究作為未來極微縮電晶體的通道材料。", u"<strong>凡得瓦異質結構</strong>：像樂高積木一樣把不同的二維材料堆疊起來，設計出全新的性質。"]),
   ("h", u"魔角石墨烯"),
   ("p", u"2018 年，麻省理工學院的<strong>哈里洛－埃雷羅</strong>團隊（第一作者是當時的研究生<strong>曹原</strong>）把兩層石墨烯以約 <strong>1.1°</strong> 的「魔角」扭轉疊在一起，發現它變成了<strong>超導體</strong>與關聯絕緣體。扭轉造成的疊紋（moiré）圖案讓電子的能帶變得極平，電子之間的交互作用主導了一切。這開啟了一個新領域：<strong>扭轉電子學</strong>（twistronics）。"),
  ],
  u"理論認為嚴格二維晶體不穩定，2004 年曼徹斯特大學海姆與諾沃肖洛夫用透明膠帶反覆撕薄石墨，在矽晶片上找到一個原子厚的石墨烯，2010 年諾貝爾物理獎，海姆也因青蛙磁浮獲搞笑諾貝爾獎；石墨烯抗拉強度最高之一、電子遷移率極高熱導率可比鑽石、單層吸收約 2.3% 可見光等於 π 乘精細結構常數、連氦都無法穿過；蜂巢晶格在 K 點價帶與傳導帶相接，E = ±ħvF|k| 線性為狄拉克錐，有效質量為零如無質量相對論粒子速度約光速 1/300，可研究狄拉克方程，無能隙難做數位開關；二維家族有 hBN 絕緣墊子、MoS2 等過渡金屬二硫族化物單層直接能隙半導體、凡得瓦異質結構如樂高堆疊；2018 年 MIT 哈里洛－埃雷羅團隊（第一作者曹原）以約 1.1° 魔角扭轉雙層石墨烯發現超導與關聯絕緣，疊紋使能帶極平，開啟扭轉電子學。",
  [u"石墨烯是如何被發現的？", u"什麼是狄拉克錐？它代表電子有什麼特性？", u"什麼是魔角石墨烯？"]),

lesson(u"量子霍爾效應與拓撲材料", u"形狀不變的物理",
  [u"了解量子霍爾效應與電阻標準", u"理解拓撲在凝態物理中的意義", u"認識拓撲絕緣體"],
  [("h", u"量子霍爾效應"),
   ("p", u"1980 年，德國物理學家<strong>馮．克立曾</strong>在極低溫與強磁場下，量測矽電晶體中二維電子系統的霍爾電阻（" + LS(18) + u"）。古典理論預期霍爾電阻隨磁場平滑地增加，他卻看到了一系列平坦的<strong>平台</strong>，平台上的霍爾電阻精確地等於"),
   D(r"R_H = \frac{h}{\nu e^2},\qquad \nu = 1, 2, 3, \ldots"),
   ("p", u"只由兩個基本常數決定，和樣品的材料、形狀、純度<strong>完全無關</strong>，精確度達到十億分之一以上。他獲得 1985 年諾貝爾物理獎。h/e² ≈ 25,812.807 Ω 被稱為<strong>馮．克立曾常數</strong>，成為全世界的<strong>電阻標準</strong>；2019 年國際單位制重新定義後，它和 h、e 一樣是精確的定義值。"),
   ("p", u"1982 年，崔琦、施特默與勞夫林發現在更純的樣品中，ν 也可以是<strong>分數</strong>（例如 1/3）——分數量子霍爾效應，電子集體形成帶有分數電荷的準粒子（1998 年諾貝爾物理獎）。"),
   ("h", u"為什麼這麼精確：拓撲"),
   ("p", u"<strong>拓撲學</strong>研究在連續變形下不變的性質：咖啡杯和甜甜圈在拓撲上相同（都有一個洞），和球不同（見" + X("topology", u"拓撲學") + u"）。洞的數目是一個整數，不能連續地改變。1982 年，<strong>索利斯</strong>等人證明：量子霍爾平台的整數 ν，其實是電子能帶波函數的一個<strong>拓撲不變量</strong>（陳數）。正因為它是拓撲的，雜質與缺陷這些「小變形」改變不了它——這解釋了驚人的精確度。"),
   ("h", u"邊緣態"),
   ("p", u"量子霍爾系統的內部是絕緣的，但在樣品的<strong>邊緣</strong>，有只能單向流動的導電通道。邊緣態的存在是由內部的拓撲保證的：兩個拓撲不同的區域（樣品與真空）交界處，能隙必須「關閉」。這些通道不會被雜質反向散射，所以沒有能量損耗。"),
   ("h", u"拓撲絕緣體"),
   ("p", u"2005～2007 年，理論家（凱恩、梅雷、張首晟等）預測：即使<strong>不需要磁場</strong>，某些材料（因為強的自旋－軌道耦合）也有拓撲性質——<strong>拓撲絕緣體</strong>：內部是絕緣體，表面卻是導體，表面的電子自旋與運動方向互相鎖定。2007 年在碲化汞量子井中、隨後在碲化鉍（Bi₂Te₃，也是常見的熱電材料）等材料中被實驗證實。"),
   ("p", u"2016 年諾貝爾物理獎頒給<strong>索利斯</strong>、<strong>霍爾丹</strong>與<strong>考斯特利茲</strong>，表彰他們把拓撲引進凝態物理的理論工作（見" + X("nobel-physics", u"諾貝爾物理獎") + u"）。拓撲材料被寄望用於低耗能電子元件與抗干擾的拓撲量子計算，但距離實用仍有很長的路。"),
  ],
  u"1980 年馮．克立曾在極低溫強磁場量測矽電晶體二維電子霍爾電阻，看到平台 R_H = h/(νe²)，只由基本常數決定與材料形狀純度無關精確度十億分之一以上，1985 年諾貝爾獎，h/e² ≈ 25,812.807 Ω 為馮．克立曾常數與電阻標準，2019 年 SI 重新定義後為精確定義值；1982 年崔琦施特默勞夫林發現分數量子霍爾效應如 ν = 1/3 分數電荷準粒子 1998 年諾貝爾獎；拓撲研究連續變形不變性質如咖啡杯與甜甜圈，1982 年索利斯等證明 ν 是能帶波函數拓撲不變量陳數，故雜質缺陷改不了解釋精確度；內部絕緣邊緣有單向導電通道由拓撲保證，不被反向散射無損耗；2005～2007 年凱恩梅雷張首晟等預測不需磁場因強自旋軌道耦合的拓撲絕緣體內部絕緣表面導電自旋與運動鎖定，2007 年碲化汞量子井及碲化鉍等證實；2016 年諾貝爾獎索利斯霍爾丹考斯特利茲，寄望低耗能元件與拓撲量子計算。",
  [u"量子霍爾效應為什麼能作為電阻的標準？", u"拓撲不變量是什麼意思？為什麼它能解釋量子霍爾效應的精確度？", u"拓撲絕緣體和一般絕緣體有什麼不同？"]),

lesson(u"固態物理與現代科技", u"從實驗室到口袋",
  [u"串連固態物理與資訊科技", u"了解摩爾定律與其極限", u"認識固態物理的前沿方向"],
  [("h", u"資訊科技的物理基礎"),
   ("t", [u"元件", u"物理原理", u"本課"], [[u"電晶體與 CPU", u"能帶、摻雜、p-n 接面、場效應", LS(16) + u"、" + LS(19)], [u"快閃記憶體（SSD）", u"電子穿隧進出浮動閘極（量子穿隧）", u"—"], [u"硬碟", u"鐵磁性、巨磁阻", LS(21)], [u"LED、雷射二極體", u"直接能隙、電子電洞結合", LS(20)], [u"影像感測器（手機相機）", u"光吸收產生電子電洞對", LS(20)], [u"顯示器", u"液晶、OLED、薄膜電晶體（非晶矽）", LS(7)], [u"石英振盪器（時脈）", u"壓電效應（晶體變形產生電壓）", u"—"]]),
   ("p", u"一支手機裡，幾乎每一個零件都是固態物理的產物。"),
   ("h", u"摩爾定律"),
   ("p", u"1965 年，英特爾共同創辦人<strong>摩爾</strong>觀察到：積體電路上的電晶體數目大約每一到兩年加倍。這個趨勢持續了半個世紀以上——從 1971 年 Intel 4004 的約 2,300 顆，到今天的數百億顆。驅動力是<strong>微縮</strong>：電晶體越小，越快、越省電、越便宜（見" + X("device-physics", u"半導體元件物理") + u"）。"),
   ("h", u"微縮的物理極限"),
   ("ul", [u"<strong>量子穿隧</strong>：閘極氧化層只剩幾個原子厚時，電子直接穿隧過去，造成漏電。解方：高介電常數材料（high-k）。", u"<strong>短通道效應</strong>：閘極控制不住通道。解方：從平面電晶體變成立體的鰭式（FinFET）、再到環繞式閘極（GAA）。", u"<strong>散熱</strong>：功率密度過高（" + LS(11) + u"）。", u"<strong>原子的離散性</strong>：一個通道中只有少數幾個摻雜原子，位置的隨機變化造成元件之間的差異（" + LS(8) + u"）。"]),
   ("p", u"台灣的半導體產業站在這場微縮競賽的最前線。今天的「奈米」製程節點名稱已經不再對應任何實際的物理尺寸，而是代表技術世代。"),
   ("h", u"前沿方向"),
   ("ul", [u"<strong>量子材料</strong>：拓撲材料（" + LS(24) + u"）、魔角二維材料（" + LS(23) + u"）、強關聯電子系統。", u"<strong>量子計算</strong>：超導量子位元（" + LS(22) + u"）、半導體自旋量子位元、鑽石 NV 中心（見" + X("quantum-computing", u"量子計算") + u"）。", u"<strong>能源材料</strong>：鈣鈦礦太陽能電池（" + LS(3) + u"）、固態電池、熱電材料。", u"<strong>寬能隙半導體</strong>：SiC、GaN 用於電動車與電網（" + LS(16) + u"）。", u"<strong>神經形態計算</strong>：用模仿神經突觸的材料與元件做 AI 運算。"]),
  ],
  u"電晶體 CPU 靠能帶摻雜 p-n 接面場效應、快閃記憶體電子穿隧浮動閘極、硬碟鐵磁性巨磁阻、LED 雷射直接能隙、影像感測器光吸收產生電子電洞、顯示器液晶 OLED 非晶矽薄膜電晶體、石英振盪器壓電效應，手機幾乎每個零件都是固態物理產物；1965 年摩爾觀察電晶體數約每一到兩年加倍，從 1971 年 Intel 4004 約 2,300 顆到今數百億顆，驅動力是微縮；物理極限有量子穿隧漏電（high-k）、短通道效應（FinFET 到 GAA）、散熱、摻雜原子離散性造成差異；台灣半導體在微縮最前線，奈米節點名稱已不對應實際尺寸；前沿有量子材料、量子計算（超導自旋 NV）、能源材料（鈣鈦礦固態電池熱電）、寬能隙半導體、神經形態計算。",
  [u"舉出三個手機中的元件，並說明它們的固態物理原理。", u"摩爾定律面臨哪些物理極限？", u"你認為哪一個固態物理的前沿方向最有潛力？為什麼？"]),

lesson(u"總結", u"多者異也",
  [u"整理整門課的重點", u"理解固態物理的核心思想", u"了解延伸學習的方向"],
  [("h", u"整門課回顧"),
   ("t", [u"模組", u"核心"], [[u"晶體結構", u"晶格與基底、14 種布拉維晶格、FCC/BCC/HCP、米勒指數、倒晶格與布里淵區"], [u"繞射與真實晶體", u"布拉格定律、準晶與非晶、點缺陷、差排與強度"], [u"晶格振動", u"色散關係、聲學與光學支、聲子、愛因斯坦與德拜熱容、熱傳導與熱膨脹"], [u"固體中的電子", u"自由電子、費米能階、布洛赫定理、能帶與能隙、金屬／半導體／絕緣體、有效質量與電洞、霍爾效應"], [u"半導體與新奇材料", u"摻雜與 p-n 接面、LED 與太陽能、磁性、超導、石墨烯、拓撲材料、現代科技"]]),
   ("h", u"三個核心思想"),
   ("ol", [u"<strong>對稱性</strong>：晶體的週期性讓 10<sup>23</sup> 個粒子的問題變得可解：布洛赫定理、布里淵區、能帶。", u"<strong>量子力學</strong>：包立原理、費米－狄拉克統計、聲子的量子化，解釋了古典物理無法解釋的一切。", u"<strong>湧現與準粒子</strong>：大量粒子集體的行為產生全新的現象與「粒子」——聲子、電洞、庫柏對、狄拉克費米子。「多者異也」。"]),
   ("h", u"延伸學習"),
   ("p", u"經典教科書有基泰爾的《固態物理導論》（入門）與艾希克羅夫特－默敏的《固態物理》（進階）。延伸方向：凝態場論、半導體物理與元件、磁學、超導、計算材料科學（DFT）、奈米科學。延伸：" + X("quantum-mechanics", u"量子力學") + u"、" + X("statistical-physics", u"統計物理") + u"、" + X("device-physics", u"半導體元件物理") + u"、" + X("superconductivity", u"超導") + u"、" + X("materials-science", u"材料科學") + u"。"),
  ],
  u"整門課涵蓋晶體結構（晶格基底 14 種布拉維 FCC BCC HCP 米勒指數倒晶格布里淵區）、繞射與真實晶體（布拉格準晶非晶點缺陷差排）、晶格振動（色散聲學光學支聲子愛因斯坦德拜熱容熱傳導熱膨脹）、固體電子（自由電子費米能階布洛赫能帶金屬半導體絕緣體有效質量電洞霍爾）、半導體與新奇材料（摻雜 p-n LED 太陽能磁性超導石墨烯拓撲現代科技）；三核心思想為對稱性使 10^23 粒子問題可解、量子力學包立原理費米－狄拉克聲子量子化、湧現與準粒子多者異也；教科書基泰爾固態物理導論、艾希克羅夫特－默敏固態物理，延伸凝態場論半導體磁學超導 DFT 奈米科學。",
  [u"固態物理的三個核心思想是什麼？", u"舉一個「多者異也」的例子。", u"本課中你覺得最令人驚訝的現象是什麼？為什麼？"]),
]),
]
